// Site adapters: capture a conversation from INSIDE the logged-in page, where the full data lives.
// Each adapter gets a Net (same-origin JSON with the user's session; cross-origin binaries via the
// extension background), so the logic is unit-testable without a browser.

import type { CapturedFile, LossItem, ParsedConversation } from '../../src/core/schema.ts';
import { isRecord } from '../../src/core/util.ts';
import { parseChatGPTConversation } from '../../src/parsers/chatgpt.ts';
import { parseClaudeExport } from '../../src/parsers/claude.ts';
import { extractSandboxReferences } from '../../src/recover/artifacts.ts';

export interface Net {
  json(url: string, init?: { headers?: Record<string, string> }): Promise<unknown>;
  /** Fetch bytes (cross-origin allowed via the extension). */
  binary(url: string): Promise<{ base64: string; type: string; size: number }>;
}

export interface CaptureContext {
  url: URL;
  net: Net;
  doc: Document;
  maxFileBytes?: number;
  maxTotalBytes?: number;
}

export interface CaptureResult {
  parsed: ParsedConversation;
  captured: number; // files captured as bytes
  failed: string[]; // files we tried and could not get
}

export interface ComposerSpec {
  input: string[]; // selectors, first match wins
  file?: string[];
}

export interface Adapter {
  id: 'chatgpt' | 'claude' | 'gemini' | 'dom';
  label: string;
  newChatUrl?: string;
  hosts: string[];
  composer: ComposerSpec;
  conversationId(url: URL): string | undefined;
  capture(ctx: CaptureContext): Promise<CaptureResult>;
}

const MB = 1024 * 1024;

// ───────────────────────────── ChatGPT ─────────────────────────────

export const chatgpt: Adapter = {
  id: 'chatgpt',
  label: 'ChatGPT',
  newChatUrl: 'https://chatgpt.com/',
  hosts: ['chatgpt.com', 'chat.openai.com'],
  composer: { input: ['#prompt-textarea', 'div[contenteditable="true"]', 'textarea'], file: ['input[type="file"]:not([accept^="image"])', 'input[type="file"]'] },
  conversationId: (u) => u.pathname.match(/\/c\/([0-9a-f-]{20,})/i)?.[1],
  async capture({ url, net, maxFileBytes = 20 * MB, maxTotalBytes = 80 * MB }) {
    const id = this.conversationId(url);
    if (!id) throw new Error('Open a saved ChatGPT conversation (URL /c/<id>) to capture it.');
    const session = (await net.json('/api/auth/session')) as { accessToken?: string };
    if (!session?.accessToken) throw new Error('Not signed in to ChatGPT in this tab.');
    const headers = { authorization: `Bearer ${session.accessToken}` };
    const conv = (await net.json(`/backend-api/conversation/${id}`, { headers })) as Record<string, unknown>;
    const parsed = parseChatGPTConversation(conv, { kind: 'chatgpt-export', url: url.href });
    parsed.source = { ...parsed.source, kind: 'chatgpt-export', tool: 'ChatGPT (captured in page)', url: url.href };

    // Generated files: every sandbox path the conversation links to, fetched while the sandbox is alive.
    const wanted = new Map<string, string>(); // path -> message id
    for (const e of parsed.events) for (const op of extractSandboxReferences(e.text, e.id)) if (!wanted.has(op.path)) wanted.set(op.path, e.id);
    const capturedFiles: CapturedFile[] = [];
    const failed: string[] = [];
    let total = 0;
    for (const [path, messageId] of wanted) {
      try {
        const r = (await net.json(`/backend-api/conversation/${id}/interpreter/download?message_id=${encodeURIComponent(messageId)}&sandbox_path=${encodeURIComponent(path)}`, { headers })) as { download_url?: string; error_code?: string };
        if (!r?.download_url) throw new Error(r?.error_code ?? 'no download_url (sandbox expired?)');
        const bin = await net.binary(r.download_url);
        if (bin.size > maxFileBytes || total + bin.size > maxTotalBytes) throw new Error(`too large (${(bin.size / MB).toFixed(1)} MB)`);
        total += bin.size;
        capturedFiles.push({ path, content: bin.base64, encoding: 'base64', mimeType: bin.type, eventId: messageId, note: 'captured from the ChatGPT sandbox (exact bytes)' });
      } catch (err) {
        failed.push(`${path}: ${err instanceof Error ? err.message : String(err)}`);
      }
    }
    // User uploads (attachments / image parts) by file id.
    for (const m of Object.values((conv.mapping ?? {}) as Record<string, { message?: Record<string, unknown> }>)) {
      const atts = (m.message?.metadata as Record<string, unknown> | undefined)?.attachments;
      if (!Array.isArray(atts)) continue;
      for (const a of atts as Record<string, unknown>[]) {
        const fid = String(a.id ?? '');
        if (!fid) continue;
        const name = String(a.name ?? fid);
        try {
          const r = (await net.json(`/backend-api/files/${encodeURIComponent(fid)}/download`, { headers })) as { download_url?: string };
          if (!r?.download_url) throw new Error('no download_url');
          const bin = await net.binary(r.download_url);
          if (bin.size > maxFileBytes || total + bin.size > maxTotalBytes) throw new Error('too large');
          total += bin.size;
          capturedFiles.push({ path: `uploads/${name}`, content: bin.base64, encoding: 'base64', mimeType: bin.type, note: 'file the user uploaded (captured in page)' });
        } catch (err) {
          failed.push(`uploads/${name}: ${err instanceof Error ? err.message : String(err)}`);
        }
      }
    }
    parsed.capturedFiles = capturedFiles;
    parsed.loss = [...(parsed.loss ?? []), ...captureLoss(failed)];
    return { parsed, captured: capturedFiles.length, failed };
  },
};

// ───────────────────────────── Claude ─────────────────────────────

export const claude: Adapter = {
  id: 'claude',
  label: 'Claude',
  newChatUrl: 'https://claude.ai/new',
  hosts: ['claude.ai'],
  composer: { input: ['div.ProseMirror[contenteditable="true"]', 'div[contenteditable="true"]', 'textarea'], file: ['input[data-testid="file-upload"]', 'input[type="file"]'] },
  conversationId: (u) => u.pathname.match(/\/chat\/([0-9a-f-]{20,})/i)?.[1],
  async capture({ url, net }) {
    const id = this.conversationId(url);
    if (!id) throw new Error('Open a Claude conversation (URL /chat/<id>) to capture it.');
    const orgs = (await net.json('/api/organizations')) as { uuid: string; capabilities?: string[] }[];
    const org = (Array.isArray(orgs) ? orgs.find((o) => o.capabilities?.includes('chat')) ?? orgs[0] : undefined)?.uuid;
    if (!org) throw new Error('Not signed in to Claude in this tab.');
    const conv = await net.json(`/api/organizations/${org}/chat_conversations/${id}?tree=True&rendering_mode=messages&render_all_tools=true`);
    const [parsed] = parseClaudeExport([conv]);
    if (!parsed) throw new Error('Unexpected conversation format from claude.ai');
    parsed.source = { ...parsed.source, tool: 'Claude (captured in page)', url: url.href };
    parsed.loss = (parsed.loss ?? []).filter((l) => l.category !== 'memory');
    return { parsed, captured: 0, failed: [] };
  },
};

// ───────────────────────────── Gemini and other sites (DOM) ─────────────────────────────

function textOf(el: Element): string {
  const clone = el.cloneNode(true) as HTMLElement;
  clone.querySelectorAll('pre').forEach((pre) => {
    const code = pre.textContent ?? '';
    pre.replaceWith(Object.assign(el.ownerDocument.createElement('div'), { textContent: `\n\`\`\`\n${code.replace(/\n$/, '')}\n\`\`\`\n` }));
  });
  return (clone.innerText ?? clone.textContent ?? '').replace(/\n{3,}/g, '\n\n').trim();
}

export function domTurns(doc: Document, userSel: string, botSel: string): { role: 'user' | 'assistant'; text: string }[] {
  const nodes = [...doc.querySelectorAll(`${userSel}, ${botSel}`)];
  return nodes
    .map((n) => ({ role: (n.matches(userSel) ? 'user' : 'assistant') as 'user' | 'assistant', text: textOf(n) }))
    .filter((t) => t.text);
}

function domCapture(label: string, userSel: string, botSel: string) {
  return async ({ url, doc }: CaptureContext): Promise<CaptureResult> => {
    const turns = domTurns(doc, userSel, botSel);
    if (!turns.length) throw new Error(`No conversation found on this ${label} page.`);
    const title = (doc.title || label).replace(/\s*[-|–]\s*(Gemini|Google).*$/i, '').trim() || `${label} conversation`;
    const loss: LossItem[] = [{ category: 'dom-capture', count: turns.length, severity: 'warn', detail: `${label} was captured from the rendered page: visible text and code only. Tool outputs, files and hidden reasoning are not in the DOM.` }];
    return {
      parsed: { title, source: { kind: 'unknown', tool: `${label} (captured in page)`, url: url.href }, events: turns.map((t, i) => ({ id: `d${i + 1}`, kind: 'message', role: t.role, text: t.text })), loss },
      captured: 0,
      failed: [],
    };
  };
}

export const gemini: Adapter = {
  id: 'gemini',
  label: 'Gemini',
  newChatUrl: 'https://gemini.google.com/app',
  hosts: ['gemini.google.com'],
  composer: { input: ['rich-textarea .ql-editor', 'div[contenteditable="true"]', 'textarea'], file: ['input[type="file"]'] },
  conversationId: (u) => u.pathname.match(/\/app\/([0-9a-f]+)/i)?.[1],
  capture: domCapture('Gemini', 'user-query', 'model-response'),
};

/** Fallback for any chat page that marks roles in the DOM (many ChatGPT-like UIs do). */
export const dom: Adapter = {
  id: 'dom',
  label: 'This page',
  hosts: [],
  composer: { input: ['div[contenteditable="true"]', 'textarea'] },
  conversationId: () => undefined,
  capture: domCapture('this site', '[data-message-author-role="user"], [data-role="user"]', '[data-message-author-role="assistant"], [data-role="assistant"]'),
};

export const ADAPTERS: Adapter[] = [chatgpt, claude, gemini];

export function adapterFor(url: URL, override?: string | null): Adapter {
  if (override) return ADAPTERS.find((a) => a.id === override) ?? dom;
  return ADAPTERS.find((a) => a.hosts.includes(url.hostname)) ?? dom;
}

function captureLoss(failed: string[]): LossItem[] {
  return failed.length
    ? [{ category: 'files-not-captured', count: failed.length, severity: 'warn', detail: `Some files could not be fetched from the source (${failed.slice(0, 5).join('; ')}${failed.length > 5 ? '; …' : ''}). ChatGPT sandboxes expire, so capture soon after the work.` }]
    : [];
}

export { isRecord };

// Put a handoff INTO another AI's composer: text into the input, files onto the uploader. Never presses send.

import type { ComposerSpec } from './adapters.ts';

export function waitFor(doc: Document, selectors: string[], timeoutMs = 15000): Promise<HTMLElement | null> {
  const find = () => {
    for (const s of selectors) {
      const el = doc.querySelector<HTMLElement>(s);
      if (el) return el;
    }
    return null;
  };
  return new Promise((resolve) => {
    const hit = find();
    if (hit) return resolve(hit);
    const obs = new MutationObserver(() => {
      const el = find();
      if (el) {
        obs.disconnect();
        clearTimeout(t);
        resolve(el);
      }
    });
    obs.observe(doc.documentElement, { childList: true, subtree: true });
    const t = setTimeout(() => {
      obs.disconnect();
      resolve(find());
    }, timeoutMs);
  });
}

export async function fillComposer(doc: Document, spec: ComposerSpec, text: string): Promise<boolean> {
  const el = await waitFor(doc, spec.input);
  if (!el) return false;
  el.focus();
  if (el instanceof HTMLTextAreaElement || el instanceof HTMLInputElement) {
    const proto = el instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
    Object.getOwnPropertyDescriptor(proto, 'value')?.set?.call(el, (el.value ? el.value + '\n\n' : '') + text);
    el.dispatchEvent(new Event('input', { bubbles: true }));
    return true;
  }
  // contenteditable editors (ProseMirror, Quill, Lexical) accept insertText or a synthetic paste.
  const before = el.textContent ?? '';
  let ok = false;
  try {
    ok = doc.execCommand('insertText', false, text);
  } catch {
    ok = false;
  }
  if (!ok || (el.textContent ?? '') === before) {
    const dt = new DataTransfer();
    dt.setData('text/plain', text);
    el.dispatchEvent(new ClipboardEvent('paste', { clipboardData: dt, bubbles: true, cancelable: true }));
  }
  if ((el.textContent ?? '') === before) {
    el.textContent = before + text; // last resort
    el.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'insertText', data: text }));
  }
  return true;
}

export async function attachFiles(doc: Document, spec: ComposerSpec, files: File[]): Promise<'input' | 'paste' | 'none'> {
  if (!files.length) return 'none';
  const dt = new DataTransfer();
  for (const f of files) dt.items.add(f);
  const input = spec.file ? ((await waitFor(doc, spec.file, 4000)) as HTMLInputElement | null) : null;
  if (input && input instanceof HTMLInputElement && input.type === 'file') {
    input.files = dt.files;
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
    return 'input';
  }
  const target = await waitFor(doc, spec.input, 2000);
  if (!target) return 'none';
  target.dispatchEvent(new ClipboardEvent('paste', { clipboardData: dt, bubbles: true, cancelable: true }));
  return 'paste';
}

// Runs in the PAGE's main world at document_start. Tees streamed AI responses so Baton can keep what the
// page received while it streamed (including output that is never persisted or that a share redacts).
// Only response bodies of known conversation-stream endpoints are observed; nothing is modified or sent anywhere.

const STREAM_PATTERNS = [
  /\/backend-api\/(?:f\/)?conversation(?:\?|$)/, // ChatGPT
  /\/api\/organizations\/[^/]+\/chat_conversations\/[^/]+\/(?:completion|retry_completion)/, // Claude
  /BardFrontendService\/StreamGenerate/, // Gemini
  /\/__baton_test_stream/, // test harness
];
const MAX_BODY = 2 * 1024 * 1024;

const w = window as unknown as { __batonTap?: boolean; fetch: typeof fetch };
if (!w.__batonTap) {
  w.__batonTap = true;
  const orig = w.fetch.bind(window);
  w.fetch = async (input: RequestInfo | URL, init?: RequestInit) => {
    const res = await orig(input, init);
    try {
      const url = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;
      if (STREAM_PATTERNS.some((re) => re.test(url))) {
        res
          .clone()
          .text()
          .then((body) => window.postMessage({ source: 'baton-tap', url, status: res.status, at: new Date().toISOString(), body: body.slice(0, MAX_BODY), truncated: body.length > MAX_BODY }, window.location.origin))
          .catch(() => {});
      }
    } catch {
      /* never break the page */
    }
    return res;
  };
}

// Service worker: cross-origin byte fetches (signed file URLs), opening target tabs, relay uploads.

import { bytesToBase64 } from '../../src/core/util.ts';

declare const chrome: any;

const MAX = 50 * 1024 * 1024;

chrome.runtime.onMessage.addListener((msg: any, _sender: any, reply: (v: unknown) => void) => {
  (async () => {
    try {
      if (msg.type === 'baton:binary') {
        const res = await fetch(msg.url, { credentials: 'omit' });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const buf = new Uint8Array(await res.arrayBuffer());
        if (buf.length > MAX) throw new Error('file larger than 50 MB');
        return reply({ ok: true, base64: bytesToBase64(buf), type: res.headers.get('content-type') ?? 'application/octet-stream', size: buf.length });
      }
      if (msg.type === 'baton:open') {
        await chrome.tabs.create({ url: msg.url, active: true });
        return reply({ ok: true });
      }
      if (msg.type === 'baton:relay') {
        const res = await fetch(msg.relay.replace(/\/$/, '') + '/api/handoffs', {
          method: 'POST',
          headers: { 'content-type': 'application/json', ...(msg.token ? { authorization: `Bearer ${msg.token}` } : {}) },
          body: JSON.stringify(msg.body),
        });
        const out = await res.json();
        return reply(res.ok ? { ok: true, ...out } : { ok: false, error: out.error ?? `HTTP ${res.status}` });
      }
      reply({ ok: false, error: 'unknown message' });
    } catch (err) {
      reply({ ok: false, error: err instanceof Error ? err.message : String(err) });
    }
  })();
  return true; // async reply
});

chrome.action.onClicked.addListener((tab: any) => {
  if (tab?.id) chrome.tabs.sendMessage(tab.id, { type: 'baton:toggle' }).catch?.(() => {});
});

// Drop pending tab-to-tab handoffs older than an hour.
chrome.runtime.onStartup?.addListener(async () => {
  const all = await chrome.storage.local.get(null);
  const stale = Object.keys(all).filter((k) => k.startsWith('baton:pending:') && Date.now() - (all[k]?.createdAt ?? 0) > 3600000);
  if (stale.length) await chrome.storage.local.remove(stale);
});

// Content script: the in-page Baton panel. Capture → (copy | save | continue in another AI | send to relay).

import { buildBundle } from '../../src/core/build.ts';
import type { BatonBundle } from '../../src/core/schema.ts';
import { base64ToBytes, bytesToBase64, slugify } from '../../src/core/util.ts';
import { zip, type FileMap } from '../../src/core/zip.ts';
import { renderBundleFiles } from '../../src/render/files.ts';
import { sealedPlaintext } from '../../src/relay/client.ts';
import { seal } from '../../src/relay/seal.ts';
import { ADAPTERS, adapterFor, type Adapter, type Net } from './adapters.ts';
import { attachFiles, fillComposer } from './inject.ts';

declare const chrome: any;

interface Settings {
  relay?: string;
  token?: string;
  seal: boolean;
  redact: boolean;
}

interface Pending {
  id: string;
  createdAt: number;
  title: string;
  prompt: string;
  files: { name: string; type: string; base64: string }[];
}

const doc = document;
const testSite = doc.documentElement.dataset.batonTestSite; // only honoured by the test build's host matches
const adapter: Adapter = adapterFor(new URL(location.href), testSite);
const streams: { url: string; at: string; body: string }[] = [];
let streamBytes = 0;
let last: { bundle: BatonBundle; files: FileMap } | undefined;

// ───────── live stream tap (from tap.ts in the main world) ─────────
window.addEventListener('message', (e) => {
  if (e.source !== window || e.data?.source !== 'baton-tap') return;
  if (streamBytes > 5 * 1024 * 1024) return;
  streams.push({ url: e.data.url, at: e.data.at, body: e.data.body });
  streamBytes += e.data.body.length;
  updateTapCount();
});

// ───────── network for adapters ─────────
const net: Net = {
  async json(url, init) {
    const res = await fetch(url, { credentials: 'include', headers: init?.headers });
    if (!res.ok) throw new Error(`${new URL(url, location.href).pathname}: HTTP ${res.status}`);
    return res.json();
  },
  async binary(url) {
    const r = await chrome.runtime.sendMessage({ type: 'baton:binary', url });
    if (!r?.ok) throw new Error(r?.error ?? 'download failed');
    return r;
  },
};

async function settings(): Promise<Settings> {
  const s = (await chrome.storage.sync.get(['relay', 'token', 'seal', 'redact'])) as Partial<Settings>;
  return { relay: s.relay || undefined, token: s.token || undefined, seal: s.seal !== false, redact: s.redact !== false };
}

// ───────── capture ─────────
async function capture(): Promise<void> {
  setStatus(`Capturing from ${adapter.label}…`);
  busy(true);
  try {
    const s = await settings();
    const res = await adapter.capture({ url: new URL(location.href), net, doc });
    if (streams.length) {
      res.parsed.capturedFiles = [
        ...(res.parsed.capturedFiles ?? []),
        ...streams.map((st, i) => ({ path: `live-streams/${String(i + 1).padStart(3, '0')}.txt`, content: `# ${st.url}\n# ${st.at}\n${st.body}`, note: 'raw response stream observed in the page while it was generated' })),
      ];
    }
    const { bundle, extraFiles } = buildBundle(res.parsed, { redact: s.redact });
    const files = renderBundleFiles(bundle, { extraFiles });
    last = { bundle, files };
    renderResult(bundle, res.captured, res.failed.length);
    setStatus(`Captured "${bundle.title}".`, 'ok');
  } catch (err) {
    setStatus(err instanceof Error ? err.message : String(err), 'err');
  } finally {
    busy(false);
  }
}

// ───────── actions ─────────
async function copyPrompt(): Promise<void> {
  if (!last) return;
  try {
    await navigator.clipboard.writeText(String(last.files['PROMPT.md']));
    setStatus('Paste-ready prompt copied.', 'ok');
  } catch {
    setStatus('Clipboard blocked: use Save instead.', 'err');
  }
}

function zipBytes(): Uint8Array {
  const prefixed: FileMap = {};
  for (const [k, v] of Object.entries(last!.files)) prefixed[`${slugify(last!.bundle.title)}/${k}`] = v;
  return zip(prefixed);
}

function saveZip(): void {
  if (!last) return;
  const a = doc.createElement('a');
  a.href = URL.createObjectURL(new Blob([zipBytes() as BlobPart], { type: 'application/zip' }));
  a.download = `${slugify(last.bundle.title)}.baton.zip`;
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 3000);
}

/** Tab-to-tab: stash the handoff locally, open the target AI, and let its content script insert it. */
async function continueIn(target: Adapter): Promise<void> {
  if (!last) return;
  const id = Math.random().toString(36).slice(2, 10);
  const textFiles = last.bundle.artifacts.filter((a) => a.content !== undefined && a.encoding !== 'base64' && (a.bytes ?? 0) < 200000).slice(0, 8);
  const files: Pending['files'] = [{ name: 'HANDOFF.md', type: 'text/markdown', base64: bytesToBase64(new TextEncoder().encode(String(last.files['HANDOFF.md']))) }];
  if (target.id === 'chatgpt') files.push({ name: `${slugify(last.bundle.title)}.baton.zip`, type: 'application/zip', base64: bytesToBase64(zipBytes()) });
  else for (const a of textFiles) files.push({ name: a.path.split('/').pop() || a.path, type: 'text/plain', base64: bytesToBase64(new TextEncoder().encode(a.content!)) });
  const pending: Pending = { id, createdAt: Date.now(), title: last.bundle.title, prompt: String(last.files['PROMPT.md']), files };
  await chrome.storage.local.set({ [`baton:pending:${id}`]: pending });
  const targets = ((await chrome.storage.local.get('baton:targets'))['baton:targets'] ?? {}) as Record<string, string>;
  const base = targets[target.id] ?? target.newChatUrl!;
  await chrome.runtime.sendMessage({ type: 'baton:open', url: `${base}#baton=${id}` });
  setStatus(`Opened ${target.label}. The handoff is being inserted there. Review it, then press send.`, 'ok');
}

async function sendToRelay(): Promise<void> {
  if (!last) return;
  const s = await settings();
  if (!s.relay) return setStatus('Set a relay URL in the Baton options first.', 'err');
  busy(true);
  try {
    let body: Record<string, unknown> = { bundle: last.bundle, from: `extension:${adapter.id}` };
    let key: string | undefined;
    if (s.seal) {
      const sealed = await seal(sealedPlaintext(last.bundle, last.files));
      body = { sealed: sealed.sealed, title: last.bundle.title, from: `extension:${adapter.id}` };
      key = sealed.key;
    }
    const r = await chrome.runtime.sendMessage({ type: 'baton:relay', relay: s.relay, token: s.token, body });
    if (!r?.ok) throw new Error(r?.error ?? 'relay error');
    const link = `${String(r.url).startsWith('http') ? r.url : s.relay.replace(/\/$/, '') + r.url}${key ? `#${key}` : ''}`;
    showLink(link, r.code);
    setStatus(key ? 'Sent end-to-end encrypted: only someone with the full link can open it.' : `Sent. Pickup code ${r.code}.`, 'ok');
  } catch (err) {
    setStatus(err instanceof Error ? err.message : String(err), 'err');
  } finally {
    busy(false);
  }
}

// ───────── receiving side ─────────
async function receivePending(): Promise<void> {
  const m = location.hash.match(/baton=([a-z0-9]+)/);
  if (!m) return;
  const key = `baton:pending:${m[1]}`;
  const p = ((await chrome.storage.local.get(key))[key] ?? undefined) as Pending | undefined;
  history.replaceState(null, '', location.pathname + location.search);
  if (!p) return;
  openPanel();
  setStatus(`Inserting handoff "${p.title}"…`);
  const files = p.files.map((f) => new File([base64ToBytes(f.base64) as BlobPart], f.name, { type: f.type }));
  const how = await attachFiles(doc, adapter.composer, files);
  const filled = await fillComposer(doc, adapter.composer, p.prompt);
  await chrome.storage.local.remove(key);
  setStatus(filled ? `Handoff inserted${how !== 'none' ? ` with ${files.length} file(s)` : ''}. Review it, then press send.` : 'Could not find the message box. Use "Copy prompt" from the source tab instead.', filled ? 'ok' : 'err');
  doc.documentElement.dataset.batonReceived = filled ? `ok:${how}` : 'fail';
}

// ───────── panel UI (shadow DOM, so page CSS cannot interfere) ─────────
const host = doc.createElement('baton-panel');
const root = host.attachShadow({ mode: 'open' });
root.innerHTML = `<style>
:host{all:initial}
.fab{position:fixed;right:18px;bottom:88px;z-index:2147483646;font:700 13px/1 system-ui,sans-serif;letter-spacing:.06em;text-transform:uppercase;background:#14201b;color:#fff;border:0;border-radius:6px;padding:10px 12px;cursor:pointer;box-shadow:0 4px 14px rgba(0,0,0,.25)}
.p{position:fixed;right:18px;bottom:134px;z-index:2147483647;width:340px;max-width:calc(100vw - 36px);max-height:70vh;overflow:auto;background:#fff;color:#14201b;border:1px solid #14201b;border-radius:8px;font:14px/1.45 system-ui,sans-serif;box-shadow:0 10px 30px rgba(0,0,0,.25)}
@media (prefers-color-scheme:dark){.p{background:#161e1b;color:#e4ebe7;border-color:#9aaba3}.fab{background:#e4ebe7;color:#0f1513}.st{color:#9aaba3}button.b{background:#161e1b;color:#e4ebe7;border-color:#9aaba3}}
.h{display:flex;justify-content:space-between;align-items:center;padding:10px 12px;border-bottom:1px solid #d7dfdb;font-weight:800;letter-spacing:.08em;text-transform:uppercase;font-size:12px}
.c{padding:10px 12px;display:grid;gap:8px}
button.b{font:600 13px system-ui,sans-serif;padding:7px 10px;border-radius:5px;border:1px solid #14201b;background:#fff;color:#14201b;cursor:pointer}
button.pri{background:#2343c9;border-color:#2343c9;color:#fff}
button:disabled{opacity:.5;cursor:default}
.row{display:flex;flex-wrap:wrap;gap:6px}
.st{font-size:13px;color:#5b6b64;min-height:1.2em}.st.ok{color:#1f7a4d}.st.err{color:#b4271c}
.stats{display:grid;grid-template-columns:1fr 1fr;gap:4px 10px;font-size:13px;font-variant-numeric:tabular-nums}
.stats b{font-size:16px}
.cmp{font-size:12px;color:#1f7a4d}
.link{font:12px ui-monospace,monospace;word-break:break-all;background:rgba(127,127,127,.12);padding:6px;border-radius:4px}
.x{background:none;border:0;font-size:18px;cursor:pointer;color:inherit}
</style>
<button class="fab" id="fab" title="Baton: carry this work to another AI">Baton</button>
<div class="p" id="panel" hidden>
  <div class="h"><span>Baton · ${adapter.label}</span><button class="x" id="close" aria-label="Close">×</button></div>
  <div class="c">
    <button class="b pri" id="cap">Capture this conversation</button>
    <div class="stats" id="stats" hidden></div>
    <div class="cmp" id="cmp" hidden></div>
    <div id="acts" hidden>
      <div class="row"><button class="b" id="copy">Copy prompt</button><button class="b" id="save">Save .zip</button><button class="b" id="send">Send to relay</button></div>
      <div style="margin-top:8px;font-size:12px;font-weight:700">Continue in</div>
      <div class="row" id="targets"></div>
    </div>
    <div class="link" id="link" hidden></div>
    <div class="st" id="st" role="status">${streams.length ? '' : 'Ready.'}</div>
    <div class="st" id="tap"></div>
  </div>
</div>`;
const $ = (id: string) => root.getElementById(id) as HTMLElement;

function openPanel() {
  $('panel').hidden = false;
}
function setStatus(msg: string, kind: '' | 'ok' | 'err' = '') {
  const el = $('st');
  el.textContent = msg;
  el.className = `st ${kind}`;
}
function busy(b: boolean) {
  root.querySelectorAll('button.b').forEach((x) => ((x as HTMLButtonElement).disabled = b));
}
function updateTapCount() {
  $('tap').textContent = streams.length ? `${streams.length} live response stream(s) observed in this tab` : '';
}
function showLink(link: string, code: string) {
  const el = $('link');
  el.hidden = false;
  el.textContent = `${code}\n${link}`;
  navigator.clipboard?.writeText(link).catch(() => {});
}
function renderResult(b: BatonBundle, captured: number, failed: number) {
  const s = b.stats;
  const outputs = b.events.filter((e) => e.kind === 'tool_result' && !e.redactedBySource).length;
  $('stats').hidden = false;
  $('stats').innerHTML = [
    ['prompts', s.userMessages],
    ['tool outputs', outputs],
    ['files', s.artifacts.recovered + s.artifacts.attached],
    ['files lost', s.artifacts.lost + failed],
  ]
    .map(([k, v]) => `<div><b>${v}</b> ${k}</div>`)
    .join('');
  if (adapter.id === 'chatgpt') {
    $('cmp').hidden = false;
    $('cmp').textContent = `A share link of this chat would keep 0 tool outputs and 0 files. Captured here: ${outputs} outputs, ${captured} files.`;
  }
  $('acts').hidden = false;
  $('targets').innerHTML = '';
  for (const t of ADAPTERS.filter((a) => a.id !== adapter.id)) {
    const btn = doc.createElement('button');
    btn.className = 'b';
    btn.textContent = t.label;
    btn.onclick = () => continueIn(t);
    $('targets').appendChild(btn);
  }
}

$('fab').onclick = () => ($('panel').hidden = !$('panel').hidden);
$('close').onclick = () => ($('panel').hidden = true);
$('cap').onclick = capture;
$('copy').onclick = copyPrompt;
$('save').onclick = saveZip;
$('send').onclick = sendToRelay;
chrome.runtime.onMessage.addListener((msg: { type: string }) => {
  if (msg.type === 'baton:toggle') $('panel').hidden = !$('panel').hidden;
});

(doc.body ?? doc.documentElement).appendChild(host);
receivePending();

