const $ = (id: string) => root.getElementById(id) as HTMLElement;

function openPanel() {
  $('panel').hidden = false;
}
function setStatus(msg: string, kind: '' | 'ok' | 'err' = '') {
  const el = $('st');
  el.textContent = msg;
