    run: async (args) => {
      const { bundle } = loadBundle(String(args.bundle));
      const payload = buildSink(String(args.to) as SinkName, bundle, { jiraProject: s(args.jira_project), salesforceParentId: s(args.salesforce_parent_id) });
      if (args.post !== true) return JSON.stringify(payload, null, 2);
      return JSON.stringify(await postSink(payload), null, 2);
    },
  },
];

type Json = Record<string, unknown>;

export async function handleMessage(msg: Json): Promise<Json | undefined> {
  const id = msg.id as string | number | undefined;
  const method = msg.method as string | undefined;
  const reply = (result: unknown): Json => ({ jsonrpc: '2.0', id, result });
  const fail = (code: number, message: string): Json => ({ jsonrpc: '2.0', id, error: { code, message } });
  if (id === undefined || id === null) return undefined; // notification

  switch (method) {
    case 'initialize': {
      const requested = (msg.params as Json | undefined)?.protocolVersion as string | undefined;
      return reply({
        protocolVersion: requested && SUPPORTED.includes(requested) ? requested : SUPPORTED[0],
        capabilities: { tools: { listChanged: false } },
        serverInfo: { name: 'baton', version: VERSION },
        instructions: 'Baton moves AI work between tools. Use baton_import with a ChatGPT share link or an export/session file, then read the returned HANDOFF.md and continue the work. Respect the loss audit: lost files do not exist.',
      });
    }
    case 'ping':
      return reply({});
    case 'tools/list':
      return reply({ tools: TOOLS.map(({ run: _r, ...t }) => t) });
    case 'tools/call': {
      const params = (msg.params ?? {}) as Json;
      const tool = TOOLS.find((t) => t.name === params.name);
      if (!tool) return fail(-32602, `Unknown tool: ${String(params.name)}`);
      try {
        const text = await tool.run((params.arguments ?? {}) as Record<string, unknown>);
        return reply({ content: [{ type: 'text', text }] });
      } catch (err) {
        return reply({ content: [{ type: 'text', text: `Error: ${err instanceof Error ? err.message : String(err)}` }], isError: true });
      }
    }
    case 'resources/list':
      return reply({ resources: [] });
    case 'prompts/list':
      return reply({ prompts: [] });
    default:
      return fail(-32601, `Method not found: ${String(method)}`);
  }
}

export async function startMcpServer(): Promise<void> {
  const rl = createInterface({ input: process.stdin, crlfDelay: Infinity });
  const write = (m: Json) => process.stdout.write(JSON.stringify(m) + '\n');
  for await (const line of rl) {
    if (!line.trim()) continue;
    let msg: Json;
    try {
      msg = JSON.parse(line) as Json;
    } catch {
      write({ jsonrpc: '2.0', id: null, error: { code: -32700, message: 'Parse error' } });
      continue;
    }
    const res = await handleMessage(msg);
    if (res) write(res);
  }
}

// Node-only I/O: fetching a share URL, reading files/zips, locating Claude Code sessions, writing bundles.

import { existsSync, mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { dirname, join, relative, resolve, sep } from 'node:path';
import { inflateRawSync } from 'node:zlib';
import { unzipSync, zip, type FileMap } from '../core/zip.ts';
import { pickExportMember } from '../pipeline.ts';

export interface LoadedInput {
  text: string;
  filename: string;
  url?: string;
}

const SHARE_HOSTS = new Set(['chatgpt.com', 'chat.openai.com']);
const UA = 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36 Baton/0.1';

export function isShareUrl(s: string): boolean {
  try {
    const u = new URL(s);
    return u.protocol === 'https:' && SHARE_HOSTS.has(u.hostname) && /^\/(?:share|s)\/[A-Za-z0-9-]+\/?$/.test(u.pathname);
  } catch {
    return false;
  }
}

/** Fetch exactly one user-supplied public share page. No crawling, no auth, no retries beyond one. */
export async function fetchShare(url: string, timeoutMs = 30000): Promise<LoadedInput> {
  if (!isShareUrl(url)) {
    throw new Error(`Only public ChatGPT share links are fetched (https://chatgpt.com/share/<id>). For other sources, export the data and pass the file. Got: ${url}`);
  }
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const res = await fetch(url, { headers: { 'user-agent': UA, accept: 'text/html' }, signal: ctrl.signal, redirect: 'follow' });
    if (!res.ok) throw new Error(`Fetching share link failed: HTTP ${res.status}. The link may be private, deleted, or rate-limited. Try saving the page (Ctrl/Cmd+S) and passing the .html file.`);
    const text = await res.text();
    if (!text.includes('streamController.enqueue')) {
      throw new Error('The page did not contain conversation data (possibly a login or bot-check page). Save the page from your browser and pass the .html file instead.');
    }
    return { text, filename: 'share.html', url };
  } finally {
    clearTimeout(t);
  }
}

/** Read a file or a ZIP export. For ZIPs, conversations.json is selected automatically. */
export function readInputFile(path: string): LoadedInput {
  const buf = readFileSync(path);
  if (buf.length >= 4 && buf.readUInt32LE(0) === 0x04034b50) {
    const members = unzipSync(new Uint8Array(buf), (d) => new Uint8Array(inflateRawSync(d)), (n) => /\.(json|jsonl|html?)$/i.test(n));
    const name = pickExportMember(Object.keys(members));
    if (!name) throw new Error(`${path}: zip contains no conversations.json / .jsonl / .html`);
    return { text: new TextDecoder().decode(members[name]), filename: name };
  }
  if (buf.length >= 2 && buf[0] === 0x1f && buf[1] === 0x8b) {
    // .gz (e.g. fixtures)
    const { gunzipSync } = require_zlib();
    return { text: gunzipSync(buf).toString('utf8'), filename: path.replace(/\.gz$/, '') };
  }
  return { text: buf.toString('utf8'), filename: path };
}

function require_zlib(): typeof import('node:zlib') {
  // node:zlib is already loaded above for inflateRawSync; re-import lazily for gunzip.
  return process.getBuiltinModule('node:zlib') as typeof import('node:zlib');
}

export async function loadInput(source: string): Promise<LoadedInput> {
  if (/^https?:\/\//i.test(source)) return fetchShare(source);
  if (!existsSync(source)) throw new Error(`No such file: ${source}`);
  if (statSync(source).isDirectory()) {
    const latest = newestJsonl(source);
    if (!latest) throw new Error(`${source} is a directory without .jsonl session logs`);
    return readInputFile(latest);
  }
  return readInputFile(source);
}

// ───────────────────────────── Claude Code sessions ─────────────────────────────

export function claudeProjectsDir(): string {
  return process.env.CLAUDE_CONFIG_DIR ? join(process.env.CLAUDE_CONFIG_DIR, 'projects') : join(homedir(), '.claude', 'projects');
}

/** Claude Code stores sessions under ~/.claude/projects/<cwd with / and . replaced by ->/<session>.jsonl */
export function projectSlug(cwd: string): string {
  return cwd.replace(/[^A-Za-z0-9]/g, '-');
}

function newestJsonl(dir: string): string | undefined {
  const files = readdirSync(dir)
    .filter((f) => f.endsWith('.jsonl'))
    .map((f) => ({ f: join(dir, f), m: statSync(join(dir, f)).mtimeMs }))
    .sort((a, b) => b.m - a.m);
  return files[0]?.f;
}

export function findSession(idOrLatest = 'latest', cwd = process.cwd()): string {
  const base = claudeProjectsDir();
  const projDir = join(base, projectSlug(cwd));
  if (idOrLatest !== 'latest') {
    const direct = join(projDir, `${idOrLatest}.jsonl`);
    if (existsSync(direct)) return direct;
    for (const d of existsSync(base) ? readdirSync(base) : []) {
      const p = join(base, d, `${idOrLatest}.jsonl`);
      if (existsSync(p)) return p;
    }
    throw new Error(`Session ${idOrLatest} not found under ${base}`);
  }
  const latest = existsSync(projDir) ? newestJsonl(projDir) : undefined;
  if (!latest) throw new Error(`No Claude Code sessions found for ${cwd} (looked in ${projDir})`);
  return latest;
}

// ───────────────────────────── writing ─────────────────────────────

/** Write a file map under `outDir`, refusing any path that would escape it. Returns written paths. */
export function writeFiles(outDir: string, files: FileMap): string[] {
  const root = resolve(outDir);
  const written: string[] = [];
  for (const [rel, content] of Object.entries(files)) {
    const target = resolve(root, rel);
    if (target !== root && !target.startsWith(root + sep)) throw new Error(`Refusing to write outside ${root}: ${rel}`);
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, content);
    written.push(relative(process.cwd(), target) || target);
  }
  return written;
}

export function writeZip(path: string, files: FileMap, prefix = ''): void {
  const prefixed: FileMap = {};
  for (const [k, v] of Object.entries(files)) prefixed[prefix ? `${prefix}/${k}` : k] = v;
  mkdirSync(dirname(resolve(path)), { recursive: true });
  writeFileSync(path, zip(prefixed));
}

/** Read a bundle back (directory, bundle.json, or .zip) for verify/sink. */
export function readBundleFiles(path: string): Record<string, string> {
  const dec = new TextDecoder();
  if (statSync(path).isDirectory()) {
    const out: Record<string, string> = {};
    const walk = (d: string) => {
      for (const f of readdirSync(d)) {
        const p = join(d, f);
        if (statSync(p).isDirectory()) walk(p);
        else out[relative(path, p).split(sep).join('/')] = readFileSync(p, 'utf8');
      }
    };
    walk(path);
    return out;
  }
  const buf = readFileSync(path);
  if (buf.readUInt32LE(0) === 0x04034b50) {
    const members = unzipSync(new Uint8Array(buf), (d) => new Uint8Array(inflateRawSync(d)));
    const out: Record<string, string> = {};
    const names = Object.keys(members);
    const bundleJson = names.find((n) => n.endsWith('bundle.json'));
    const prefix = bundleJson ? bundleJson.slice(0, -'bundle.json'.length) : '';
    for (const n of names) if (n.startsWith(prefix)) out[n.slice(prefix.length)] = dec.decode(members[n]);
    return out;
  }
  return { 'bundle.json': buf.toString('utf8') };
}

// Opt-in delivery of sink payloads. Credentials come only from environment variables; nothing is stored.

import type { SinkPayload } from '../sinks/index.ts';

function need(name: string): string {
  const v = process.env[name];
  if (!v) throw new Error(`Missing environment variable ${name}`);
  return v;
}

export interface PostResult {
  ok: boolean;
  status: number;
  url: string;
  response: string;
}

export async function postSink(p: SinkPayload): Promise<PostResult> {
  let url: string;
  const headers: Record<string, string> = { 'content-type': 'application/json', accept: 'application/json' };
  let body = p.body;
  switch (p.sink) {
    case 'salesforce':
      url = need('SALESFORCE_INSTANCE_URL').replace(/\/$/, '') + p.path;
      headers.authorization = `Bearer ${need('SALESFORCE_ACCESS_TOKEN')}`;
      break;
    case 'jira': {
      url = need('JIRA_BASE_URL').replace(/\/$/, '') + p.path;
      headers.authorization = `Basic ${btoa(`${need('JIRA_EMAIL')}:${need('JIRA_API_TOKEN')}`)}`;
      const project = process.env.JIRA_PROJECT;
      const json = JSON.stringify(body);
      if (json.includes('${JIRA_PROJECT}')) {
        if (!project) throw new Error('Set JIRA_PROJECT or pass --jira-project');
        body = JSON.parse(json.replace('${JIRA_PROJECT}', project));
      }
      break;
    }
    case 'zendesk':
      url = `https://${need('ZENDESK_SUBDOMAIN')}.zendesk.com${p.path}`;
      headers.authorization = `Basic ${btoa(`${need('ZENDESK_EMAIL')}/token:${need('ZENDESK_API_TOKEN')}`)}`;
      break;
    case 'slack':
      url = need('SLACK_WEBHOOK_URL');
      break;
  }
  const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) });
  return { ok: res.ok, status: res.status, url: url.replace(/(hooks\.slack\.com\/services\/)\S+/, '$1…'), response: (await res.text()).slice(0, 2000) };
}

// ChatGPT: public share pages (HTML / turbo-stream) and official data exports (conversations.json).
// Both carry the same conversation object: { title, mapping{id:{parent,children,message}}, current_node }.

import type { BatonEvent, LossItem, ParsedConversation } from '../core/schema.ts';
import { decodeFromHtml, decodeTurboStream } from '../core/turbostream.ts';
import { asString, epochToIso, isRecord } from '../core/util.ts';

type Rec = Record<string, unknown>;
type DraftEvent = Omit<BatonEvent, 'seq' | 'hash'>;

export const REDACTED_PLACEHOLDER = 'The output of this plugin was redacted.';

/** Locate the conversation object inside a decoded share-page loader payload. */
export function findShareConversation(root: unknown): Rec {
  if (isRecord(root)) {
    const loader = root.loaderData;
    if (isRecord(loader)) {
      for (const [route, data] of Object.entries(loader)) {
        if (!route.includes('share') || !isRecord(data)) continue;
        const sr = data.serverResponse;
        if (isRecord(sr) && isRecord(sr.data) && isRecord(sr.data.mapping)) return sr.data;
      }
    }
  }
  // Fallback: depth-first search for an object with mapping + current_node.
  const seen = new Set<unknown>();
  const stack: unknown[] = [root];
  while (stack.length) {
    const v = stack.pop();
    if (!isRecord(v) && !Array.isArray(v)) continue;
    if (seen.has(v)) continue;
    seen.add(v);
    if (isRecord(v) && isRecord(v.mapping) && typeof v.current_node === 'string') return v;
    for (const child of Array.isArray(v) ? v : Object.values(v)) stack.push(child);
  }
  throw new Error('ChatGPT share: conversation data not found in page payload');
}

export function parseChatGPTShareHtml(html: string, url?: string): ParsedConversation {
  const root = decodeFromHtml(html);
  const conv = findShareConversation(root);
  return parseChatGPTConversation(conv, { kind: 'chatgpt-share', url });
}

export function parseChatGPTTurboStream(payload: string, url?: string): ParsedConversation {
  const conv = findShareConversation(decodeTurboStream(payload.trim().split('\n')[0]));
  return parseChatGPTConversation(conv, { kind: 'chatgpt-share', url });
}

/** conversations.json from the account export: an array of conversation objects. */
export function parseChatGPTExport(json: unknown): ParsedConversation[] {
  const list = Array.isArray(json) ? json : isRecord(json) ? [json] : [];
  return list.filter((c) => isRecord(c) && isRecord(c.mapping)).map((c) => parseChatGPTConversation(c as Rec, { kind: 'chatgpt-export' }));
}

function activePath(mapping: Rec, currentNode: string | undefined): Rec[] {
  const nodes: Rec[] = [];
  let id = currentNode;
  const guard = new Set<string>();
  if (!id || !isRecord(mapping[id])) {
    // No current node: pick the deepest leaf following the last child at each step.
    const rootId = Object.keys(mapping).find((k) => {
      const n = mapping[k];
      return isRecord(n) && !n.parent;
    });
    id = rootId;
    while (id && isRecord(mapping[id])) {
      const kids = (mapping[id] as Rec).children;
      if (!Array.isArray(kids) || kids.length === 0) break;
      id = String(kids[kids.length - 1]);
    }
  }
  while (id && isRecord(mapping[id]) && !guard.has(id)) {
    guard.add(id);
    const node = mapping[id] as Rec;
    nodes.push(node);
    id = typeof node.parent === 'string' ? node.parent : undefined;
  }
  return nodes.reverse();
}

/** Replace ChatGPT private-use entity markers (U+E200 name U+E202 args… U+E201) with readable text. */
export function cleanEntities(text: string, counters: { cites: number; images: number }): string {
  return text
    .replace(/([a-z_]+)((?:[^]*)*)/g, (_m, name: string, argStr: string) => {
      const args = argStr.split('').filter(Boolean);
      if (name === 'cite') {
        counters.cites++;
        return ` [cite: ${args.join(', ')}]`;
      }
      if (name === 'url' && args.length >= 2 && /^https?:\/\//.test(args[1])) return `[${args[0]}](${args[1]})`;
      if (name === 'image_group') {
        counters.images++;
        try {
          const q = JSON.parse(args[0] ?? '{}') as { query?: string[] };
          return `*[image: ${(q.query ?? []).join('; ')}]*`;
        } catch {
          return '*[image]*';
        }
      }
      return `[${name}${args.length ? ': ' + args.join(', ') : ''}]`;
    })
    .replace(/[-]/g, '');
}

/** Strip GenUI JSX (when no fallbackMarkdown exists) into plain Markdown. */
export function jsxToMarkdown(text: string, counters: { cites: number; images: number }): string {
  return text
    .replace(/<Cite refs=\{\[([^\]]*)\]\}\s*\/>/g, (_m, refs: string) => {
      counters.cites++;
      return ` [cite: ${refs.replace(/["\s]/g, '').split(',').join(', ')}]`;
    })
    .replace(/<AsyncImage[^>]*query="([^"]*)"[^>]*\/>/g, (_m, q: string) => {
      counters.images++;
      return `*[image: ${q}]*`;
    })
    .replace(/<button[^>]*GenUI\.openUrl\("([^"]+)"\)[^>]*>([\s\S]*?)<\/button>/g, (_m, url: string, label: string) => `[${label.replace(/<[^>]+>/g, '').trim()}](${url})`)
    .replace(/<title[^>]*>([\s\S]*?)<\/title\s*>?/g, '**$1**')
    .replace(/<badge[^>]*>([\s\S]*?)<\/badge>/g, '`$1`')
    .replace(/<\/?(?:box|grid|grid-item|row|text|divider|icon|list|list-item)\b[^>]*\/?>/g, '')
    .replace(/\n{3,}/g, '\n\n');
}

export interface ChatGPTOptions {
  kind: 'chatgpt-share' | 'chatgpt-export';
  url?: string;
}

export function parseChatGPTConversation(conv: Rec, opts: ChatGPTOptions): ParsedConversation {
  const mapping = (conv.mapping ?? {}) as Rec;
  const path = activePath(mapping, typeof conv.current_node === 'string' ? conv.current_node : undefined);
  const counters = { cites: 0, images: 0 };
  const events: DraftEvent[] = [];
  let userAttachments = 0;
  let imageParts = 0;
  let models = new Set<string>();

  for (const node of path) {
    const msg = node.message;
    if (!isRecord(msg)) continue;
    const author = (msg.author ?? {}) as Rec;
    const role = String(author.role ?? 'assistant');
    const content = (msg.content ?? {}) as Rec;
    const ct = String(content.content_type ?? 'text');
    const md = (msg.metadata ?? {}) as Rec;
    const recipient = typeof msg.recipient === 'string' ? msg.recipient : 'all';
    const time = epochToIso(msg.create_time);
    const model = typeof md.model_slug === 'string' ? md.model_slug : typeof md.resolved_model_slug === 'string' ? md.resolved_model_slug : undefined;
    if (model) models.add(model);
    const hiddenInUi = md.is_visually_hidden_from_conversation === true;
    const titles = Array.isArray(md.reasoning_titles) ? (md.reasoning_titles as unknown[]).map(String) : [];
    const title = typeof md.reasoning_title === 'string' ? md.reasoning_title : titles[0];
    const base = { id: String(msg.id ?? node.id ?? ''), time, model };

    // Private context: system prompts, memory, custom instructions.
    if (role === 'system' || ct === 'model_editable_context' || ct === 'user_editable_context') {
      const txt = ct === 'model_editable_context' ? asString(content.model_set_context) : partsText(content);
      if (!txt.trim()) continue; // empty scaffolding; nothing to keep or to lose
      events.push({ ...base, kind: 'note', role: 'system', text: txt, hidden: true, meta: { private: true, contentType: ct } });
      continue;
    }

    if (ct === 'thoughts') {
      const thoughts = Array.isArray(content.thoughts) ? (content.thoughts as Rec[]) : [];
      const text = thoughts
        .map((t) => {
          const s = asString(t.summary).trim();
          const c = asString(t.content).trim();
          return c ? `**${s}.** ${c}` : s ? `**${s}.**` : '';
        })
        .filter(Boolean)
        .join('\n\n');
      if (text) events.push({ ...base, kind: 'reasoning', role: 'assistant', text, meta: { granularity: 'summary' } });
      continue;
    }

    if (ct === 'reasoning_recap') {
      events.push({ ...base, kind: 'note', role: 'assistant', text: asString(content.content), meta: { recap: true } });
      continue;
    }

    if (role === 'tool') {
      const text = ct === 'execution_output' ? asString(content.text) : partsText(content) || asString(content.text) || asString(content.result);
      const redacted = text.trim() === REDACTED_PLACEHOLDER;
      events.push({
        ...base,
        kind: 'tool_result',
        role: 'tool',
        text: redacted ? '' : text,
        tool: { name: String(author.name ?? recipient), title },
        redactedBySource: redacted || undefined,
        hidden: hiddenInUi || undefined,
      });
      continue;
    }

    if (role === 'assistant' && recipient !== 'all' && recipient !== 'assistant') {
      const input = ct === 'code' ? asString(content.text) : partsText(content);
      const redacted = input.trim() === REDACTED_PLACEHOLDER || input.trim() === '';
      events.push({
        ...base,
        kind: 'tool_call',
        role: 'assistant',
        text: title ?? '',
        tool: {
          name: recipient,
          title: titles.length > 1 ? titles.join(' · ') : title,
          language: ct === 'code' ? normaliseLang(asString(content.language), input) : undefined,
          input: redacted ? undefined : input,
        },
        redactedBySource: redacted || undefined,
        hidden: hiddenInUi || undefined,
      });
      continue;
    }

    // Plain prose (user or assistant).
    let text: string;
    const dil = isRecord(md.model_dil_v2) ? md.model_dil_v2 : undefined;
    if (role === 'assistant' && dil && typeof dil.fallbackMarkdown === 'string' && dil.fallbackMarkdown.trim()) {
      text = cleanEntities(dil.fallbackMarkdown, counters);
    } else {
      const parts = Array.isArray(content.parts) ? content.parts : [];
      text = parts
        .map((p) => {
          if (typeof p === 'string') return p;
          if (isRecord(p) && String(p.content_type ?? '').includes('image')) {
            imageParts++;
            return '*[image attachment, not included by source]*';
          }
          return asString(p);
        })
        .join('\n');
      text = role === 'assistant' ? jsxToMarkdown(cleanEntities(text, counters), counters) : text;
    }
    if (role === 'user' && Array.isArray(md.attachments)) {
      for (const a of md.attachments as Rec[]) {
        userAttachments++;
        events.push({ ...base, id: `${base.id}-att-${userAttachments}`, kind: 'attachment', role: 'user', text: `Attached file: ${asString(a.name) || 'unnamed'}`, meta: { name: a.name, mimeType: a.mime_type ?? a.mimeType, size: a.size } });
      }
    }
    if (!text.trim()) continue;
    events.push({
      ...base,
      kind: 'message',
      role: role === 'user' ? 'user' : 'assistant',
      text,
      hidden: hiddenInUi || undefined,
      meta: hiddenInUi ? { channel: 'commentary' } : undefined,
    });
  }

  const loss: LossItem[] = [];
  const offPath = Object.keys(mapping).length - path.length;
  if (offPath > 0) loss.push({ category: 'branches', count: offPath, severity: 'info', detail: `${offPath} message node(s) belong to edited/regenerated branches that are not on the active path and were not exported.` });
  if (counters.cites) loss.push({ category: 'citations', count: counters.cites, severity: 'warn', detail: `${counters.cites} inline citation marker(s) point to search results that the source did not include; only marker ids survive. See links for the source's URL list.` });
  if (counters.images + imageParts) loss.push({ category: 'images', count: counters.images + imageParts, severity: 'info', detail: 'Images shown in the conversation are not included; placeholders keep their search query where available.' });
  if (userAttachments) loss.push({ category: 'user-attachments', count: userAttachments, severity: 'warn', detail: 'Files the user uploaded are referenced by name only; their contents are not part of the source.' });
  if (events.some((e) => e.kind === 'reasoning')) loss.push({ category: 'reasoning-depth', count: events.filter((e) => e.kind === 'reasoning').length, severity: 'info', detail: 'Reasoning is available as the summaries ChatGPT displays, not the full internal chain of thought.' });

  const modelInfo = isRecord(conv.model) ? asString(conv.model.slug) : typeof conv.default_model_slug === 'string' ? conv.default_model_slug : undefined;
  const sourceLinks = Array.isArray(conv.safe_urls) ? (conv.safe_urls as unknown[]).filter((u): u is string => typeof u === 'string' && /^https?:\/\//.test(u)) : [];
  const conversationId = asString(conv.conversation_id) || asString(conv.id) || undefined;

  return {
    title: asString(conv.title) || 'Untitled ChatGPT conversation',
    source: {
      kind: opts.kind,
      tool: 'ChatGPT',
      url: opts.url,
      conversationId,
      createdAt: epochToIso(conv.create_time),
      updatedAt: epochToIso(conv.update_time),
      model: modelInfo || [...models][0],
    },
    events,
    sourceLinks,
    loss,
  };
}

function partsText(content: Rec): string {
  const parts = Array.isArray(content.parts) ? content.parts : [];
  return parts.map((p) => (typeof p === 'string' ? p : asString(p))).join('\n');
}

function normaliseLang(lang: string, code: string): string {
  if (lang && lang !== 'unknown') return lang;
  if (/^\s*(bash|sh)\s+-l?c\b/.test(code) || /^\s*(cd|ls|cat|mkdir|cp|python|pip|zip)\b/.test(code)) return 'bash';
  if (/^\s*(import|from|def|print)\b/m.test(code)) return 'python';
  return '';
}

// Claude.ai account export (conversations.json) and Claude Code session logs (*.jsonl).

import type { BatonEvent, LossItem, ParsedConversation } from '../core/schema.ts';
import { asString, epochToIso, isRecord } from '../core/util.ts';

type Rec = Record<string, unknown>;
type DraftEvent = Omit<BatonEvent, 'seq' | 'hash'>;

// ───────────────────────────── claude.ai export ─────────────────────────────

export function parseClaudeExport(json: unknown): ParsedConversation[] {
  const list = Array.isArray(json) ? json : isRecord(json) ? [json] : [];
  return list.filter((c) => isRecord(c) && Array.isArray(c.chat_messages)).map((c) => parseClaudeConversation(c as Rec));
}

function parseClaudeConversation(conv: Rec): ParsedConversation {
  const events: DraftEvent[] = [];
  const attachments: { path: string; content: string; note?: string }[] = [];
  let filesWithoutContent = 0;
  let n = 0;

  for (const m of conv.chat_messages as Rec[]) {
    const role = m.sender === 'human' ? 'user' : 'assistant';
    const time = epochToIso(m.created_at);
    const baseId = asString(m.uuid) || `m${++n}`;
    const blocks = Array.isArray(m.content) ? (m.content as Rec[]) : [];
    if (blocks.length) {
      blocks.forEach((b, i) => pushBlock(events, b, `${baseId}-${i}`, role, time));
    } else if (asString(m.text).trim()) {
      events.push({ id: baseId, kind: 'message', role, time, text: asString(m.text) });
    }
    for (const a of (Array.isArray(m.attachments) ? m.attachments : []) as Rec[]) {
      const name = asString(a.file_name) || 'attachment.txt';
      const extracted = asString(a.extracted_content);
      events.push({ id: `${baseId}-att-${name}`, kind: 'attachment', role: 'user', time, text: `Attached file: ${name}`, meta: { size: a.file_size, type: a.file_type } });
      if (extracted) attachments.push({ path: `attachments/${name}`, content: extracted, note: 'text extracted by Claude at upload time' });
      else filesWithoutContent++;
    }
    for (const f of (Array.isArray(m.files) ? m.files : []) as Rec[]) {
      filesWithoutContent++;
      events.push({ id: `${baseId}-file-${asString(f.file_name)}`, kind: 'attachment', role: 'user', time, text: `Attached file: ${asString(f.file_name) || 'file'}` });
    }
  }

  const loss: LossItem[] = [];
  if (filesWithoutContent) loss.push({ category: 'user-attachments', count: filesWithoutContent, severity: 'warn', detail: 'Uploaded files without extracted text (images, binaries) are referenced by name only.' });
  loss.push({ category: 'memory', count: 1, severity: 'info', detail: 'Claude exports do not include memory or project knowledge; only conversation messages.' });

  return {
    title: asString(conv.name) || 'Untitled Claude conversation',
    source: { kind: 'claude-export', tool: 'Claude', conversationId: asString(conv.uuid) || undefined, createdAt: epochToIso(conv.created_at), updatedAt: epochToIso(conv.updated_at) },
    events,
    attachments,
    loss,
  };
}

// ───────────────────────────── shared block handling ─────────────────────────────

function pushBlock(events: DraftEvent[], b: Rec, id: string, role: 'user' | 'assistant', time?: string, model?: string): void {
  const type = asString(b.type);
  if (type === 'text') {
    const text = asString(b.text);
    if (text.trim()) events.push({ id, kind: 'message', role, time, model, text });
  } else if (type === 'thinking' || type === 'redacted_thinking') {
    const text = asString(b.thinking);
    events.push({
      id,
      kind: 'reasoning',
      role: 'assistant',
      time,
      model,
      text,
      redactedBySource: !text.trim() || type === 'redacted_thinking' || undefined,
      meta: { granularity: 'full' },
    });
  } else if (type === 'tool_use' || type === 'server_tool_use') {
    const input = b.input;
    const name = asString(b.name) || 'tool';
    const args = FILE_TOOLS.has(name) && isRecord(input) ? input : undefined;
    events.push({ id, kind: 'tool_call', role: 'assistant', time, model, text: describeToolCall(name, input), tool: { name, callId: asString(b.id) || undefined, input: toolInputText(name, input), language: toolLang(name), args } });
  } else if (type === 'tool_result' || type.endsWith('_tool_result')) {
    const text = toolResultText(b.content);
    events.push({ id, kind: 'tool_result', role: 'tool', time, text, tool: { name: asString(b.name) || 'tool', callId: asString(b.tool_use_id) || undefined }, meta: b.is_error ? { isError: true } : undefined });
  } else if (type === 'image' || type === 'document') {
    events.push({ id, kind: 'attachment', role, time, text: `*[${type} attachment, binary content not included]*` });
  }
}

function describeToolCall(name: string, input: unknown): string {
  if (!isRecord(input)) return name;
  const hint = input.description ?? input.file_path ?? input.path ?? input.query ?? input.url ?? input.pattern ?? input.command;
  return hint ? `${name}: ${asString(hint).split('\n')[0].slice(0, 160)}` : name;
}

// Tools whose structured args drive file recovery (see recover/artifacts.ts).
const FILE_TOOLS = new Set(['Write', 'Edit', 'MultiEdit', 'NotebookEdit']);

function toolInputText(name: string, input: unknown): string {
  if (isRecord(input)) {
    if (name === 'Bash' && typeof input.command === 'string') return input.command;
    // File bodies live in tool.args and are recovered as artifacts; keep the display compact.
    if (name === 'Write' && typeof input.content === 'string') return `${asString(input.file_path)}  (${input.content.length} chars → recovered file)`;
    if (name === 'Edit') return `${asString(input.file_path)}  (edit: ${asString(input.old_string).length} → ${asString(input.new_string).length} chars)`;
  }
  return asString(input);
}

function toolLang(name: string): string | undefined {
  if (name === 'Bash') return 'bash';
  return 'json';
}

function toolResultText(content: unknown): string {
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) return asString(content);
  return (content as Rec[])
    .map((c) => {
      if (c.type === 'text') return asString(c.text);
      if (c.type === 'image') return '*[image output]*';
      if (c.type === 'tool_reference') return `(tool loaded: ${asString(c.tool_name)})`;
      return asString(c);
    })
    .join('\n');
}

// ───────────────────────────── Claude Code JSONL ─────────────────────────────

const SYSTEM_REMINDER = /<system-reminder>[\s\S]*?<\/system-reminder>/g;

export function parseClaudeCodeJsonl(text: string): ParsedConversation {
  const events: DraftEvent[] = [];
  let title = '';
  let sessionId: string | undefined;
  let cwd: string | undefined;
  let gitBranch: string | undefined;
  let model: string | undefined;
  let firstTime: string | undefined;
  let lastTime: string | undefined;
  let reminders = 0;
  let badLines = 0;
  let sidechain = 0;
  const toolNames = new Map<string, string>();

  const lines = text.split('\n');
  lines.forEach((line, li) => {
    if (!line.trim()) return;
    let o: Rec;
    try {
      o = JSON.parse(line) as Rec;
    } catch {
      badLines++;
      return;
    }
    if (o.type === 'summary' && typeof o.summary === 'string' && !title) title = o.summary;
    if (o.type !== 'user' && o.type !== 'assistant') return;
    const msg = o.message;
    if (!isRecord(msg)) return;
    sessionId ??= asString(o.sessionId) || undefined;
    cwd ??= asString(o.cwd) || undefined;
    gitBranch ??= asString(o.gitBranch) || undefined;
    const time = epochToIso(o.timestamp);
    if (time) {
      firstTime ??= time;
      lastTime = time;
    }
    if (o.isSidechain) sidechain++;
    const id = asString(o.uuid) || `l${li}`;
    const role = o.type === 'user' ? 'user' : 'assistant';
    const m = typeof msg.model === 'string' ? msg.model : undefined;
    if (m && !m.startsWith('<')) model = m;
    const isMeta = o.isMeta === true;

    if (typeof msg.content === 'string') {
      const cleaned = msg.content.replace(SYSTEM_REMINDER, () => {
        reminders++;
        return '';
      });
      if (!cleaned.trim()) return;
      const priv = isMeta || /^<(?:command-|local-command-)/.test(cleaned.trim());
      events.push({ id, kind: priv ? 'note' : 'message', role, time, text: cleaned.trim(), hidden: priv || undefined, meta: priv ? { private: isMeta } : o.isSidechain ? { sidechain: true } : undefined });
      return;
    }
    if (!Array.isArray(msg.content)) return;
    (msg.content as Rec[]).forEach((b, i) => {
      if (b.type === 'text' && typeof b.text === 'string') {
        const cleaned = b.text.replace(SYSTEM_REMINDER, () => {
          reminders++;
          return '';
        });
        if (!cleaned.trim()) return;
        b = { ...b, text: cleaned.trim() };
      }
      if (b.type === 'tool_use') toolNames.set(asString(b.id), asString(b.name));
      if (b.type === 'tool_result') b = { ...b, name: toolNames.get(asString(b.tool_use_id)) ?? 'tool', content: stripReminders(b.content, () => reminders++) };
      const before = events.length;
      pushBlock(events, b, `${id}-${i}`, role, time, m);
      if (isMeta) for (let k = before; k < events.length; k++) events[k] = { ...events[k], hidden: true, meta: { ...(events[k].meta ?? {}), private: true } };
      if (o.isSidechain) for (let k = before; k < events.length; k++) events[k] = { ...events[k], meta: { ...(events[k].meta ?? {}), sidechain: true } };
    });
  });

  if (!title) {
    const firstUser = events.find((e) => e.kind === 'message' && e.role === 'user' && e.text.trim().length > 3);
    title = firstUser ? firstUser.text.split('\n')[0].slice(0, 80) : 'Claude Code session';
  }

  const loss: LossItem[] = [];
  const encrypted = events.filter((e) => e.kind === 'reasoning' && e.redactedBySource).length;
  if (encrypted) loss.push({ category: 'reasoning-depth', count: encrypted, severity: 'info', detail: 'Thinking blocks are stored as signatures only (no plaintext) in this log, so reasoning cannot be transferred. Decisions are captured in the visible messages and tool calls.' });
  if (reminders) loss.push({ category: 'harness-context', count: reminders, severity: 'info', detail: 'Harness-injected <system-reminder> blocks were removed (private runtime context, not part of the work).' });
  if (badLines) loss.push({ category: 'unreadable-lines', count: badLines, severity: 'warn', detail: 'Some JSONL lines could not be parsed and were skipped.' });
  if (sidechain) loss.push({ category: 'subagents', count: sidechain, severity: 'info', detail: 'Sub-agent (sidechain) traffic is included and tagged; it may duplicate summaries already in the main thread.' });

  return {
    title,
    source: { kind: 'claude-code', tool: 'Claude Code', conversationId: sessionId, createdAt: firstTime, updatedAt: lastTime, model, cwd, gitBranch },
    events,
    loss,
  };
}

function stripReminders(content: unknown, onHit: () => void): unknown {
  if (typeof content === 'string') return content.replace(SYSTEM_REMINDER, () => (onHit(), ''));
  if (Array.isArray(content)) return content.map((c) => (isRecord(c) && typeof c.text === 'string' ? { ...c, text: c.text.replace(SYSTEM_REMINDER, () => (onHit(), '')) } : c));
  return content;
}

// Detect the format of an input and dispatch to the right parser.

import type { ParsedConversation, SourceKind } from '../core/schema.ts';
import { isRecord } from '../core/util.ts';
import { parseChatGPTExport, parseChatGPTShareHtml, parseChatGPTTurboStream } from './chatgpt.ts';
import { parseClaudeCodeJsonl, parseClaudeExport } from './claude.ts';
import { looksLikeMessages, parseMessagesLog } from './generic.ts';

export interface DetectResult {
  kind: SourceKind | 'baton-bundle';
  reason: string;
}

export function detectFormat(text: string, filename = ''): DetectResult {
  const t = text.trimStart();
  const name = filename.toLowerCase();
  if (t.startsWith('<') || name.endsWith('.html') || name.endsWith('.htm')) {
    if (t.includes('streamController.enqueue')) return { kind: 'chatgpt-share', reason: 'HTML with React Router stream (ChatGPT share page)' };
    return { kind: 'unknown', reason: 'HTML without a recognised conversation payload' };
  }
  if (name.endsWith('.jsonl') || isJsonl(t)) {
    if (/"type"\s*:\s*"(?:user|assistant|summary)"/.test(t.slice(0, 200000)) && /"sessionId"|"parentUuid"/.test(t.slice(0, 200000))) {
      return { kind: 'claude-code', reason: 'JSON Lines with Claude Code session records' };
    }
  }
  if (t.startsWith('[{"_') || /^\[\{"_\d+":/.test(t)) return { kind: 'chatgpt-share', reason: 'raw turbo-stream payload' };
  let json: unknown;
  try {
    json = JSON.parse(t);
  } catch {
    return { kind: 'unknown', reason: 'not JSON, JSONL or a recognised HTML page' };
  }
  const first = Array.isArray(json) ? json[0] : json;
  if (isRecord(first)) {
    if (first.schema === 'baton.bundle/v1') return { kind: 'baton-bundle', reason: 'already a Baton bundle' };
    if (isRecord(first.mapping)) return { kind: 'chatgpt-export', reason: 'conversation objects with a `mapping` tree (ChatGPT export)' };
    if (Array.isArray(first.chat_messages)) return { kind: 'claude-export', reason: 'conversation objects with `chat_messages` (Claude export)' };
  }
  if (looksLikeMessages(json)) return { kind: 'openai-messages', reason: '[{role, content}] message list' };
  return { kind: 'unknown', reason: 'JSON, but no known conversation shape' };
}

function isJsonl(t: string): boolean {
  const lines = t.split('\n', 3).filter(Boolean);
  if (lines.length < 2) return false;
  return lines.every((l) => l.trim().startsWith('{') && l.trim().endsWith('}'));
}

/** Parse any supported input into one or more conversations. */
export function parseAny(text: string, filename = '', url?: string): ParsedConversation[] {
  const d = detectFormat(text, filename);
  switch (d.kind) {
    case 'chatgpt-share':
      return [text.trimStart().startsWith('<') ? parseChatGPTShareHtml(text, url) : parseChatGPTTurboStream(text, url)];
    case 'chatgpt-export':
      return parseChatGPTExport(JSON.parse(text));
    case 'claude-export':
      return parseClaudeExport(JSON.parse(text));
    case 'claude-code':
      return [parseClaudeCodeJsonl(text)];
    case 'openai-messages':
      return [parseMessagesLog(JSON.parse(text), filename.replace(/\.[^.]+$/, '') || undefined)];
    default:
      throw new Error(`Unsupported input${filename ? ` (${filename})` : ''}: ${d.reason}`);
  }
}

// Generic chat-completions style logs: [{role, content}] or {messages: [...]}.
// Covers OpenAI/Anthropic API request logs, LangChain dumps, Open WebUI exports, etc.

import type { BatonEvent, ParsedConversation } from '../core/schema.ts';
import { asString, isRecord } from '../core/util.ts';

type Rec = Record<string, unknown>;

export function looksLikeMessages(json: unknown): boolean {
  const list = isRecord(json) && Array.isArray(json.messages) ? json.messages : json;
  return Array.isArray(list) && list.length > 0 && list.every((m) => isRecord(m) && typeof m.role === 'string' && 'content' in m);
}

export function parseMessagesLog(json: unknown, title = 'Imported conversation'): ParsedConversation {
  const root = isRecord(json) ? json : {};
  const list = (Array.isArray(json) ? json : (root.messages as unknown[])) as Rec[];
  const events: Omit<BatonEvent, 'seq' | 'hash'>[] = [];
  list.forEach((m, i) => {
    const role = m.role === 'user' || m.role === 'assistant' || m.role === 'tool' ? m.role : 'system';
    const id = `m${i + 1}`;
    if (Array.isArray(m.tool_calls)) {
      for (const tc of m.tool_calls as Rec[]) {
        const fn = isRecord(tc.function) ? tc.function : {};
        events.push({ id: `${id}-${asString(tc.id)}`, kind: 'tool_call', role: 'assistant', text: asString(fn.name), tool: { name: asString(fn.name) || 'tool', input: asString(fn.arguments), callId: asString(tc.id), language: 'json' } });
      }
    }
    const content = Array.isArray(m.content)
      ? (m.content as Rec[]).map((c) => (typeof c === 'string' ? c : asString(c.text ?? c))).join('\n')
      : asString(m.content);
    if (!content.trim()) return;
    if (role === 'tool') {
      events.push({ id, kind: 'tool_result', role: 'tool', text: content, tool: { name: asString(m.name) || 'tool', callId: asString(m.tool_call_id) || undefined } });
    } else {
      events.push({ id, kind: role === 'system' ? 'note' : 'message', role, text: content, hidden: role === 'system' || undefined, meta: role === 'system' ? { private: true } : undefined });
    }
  });
  return {
    title: asString(root.title) || title,
    source: { kind: 'openai-messages', tool: 'Chat log', model: asString(root.model) || undefined },
    events,
  };
}

// Browser-safe end-to-end pipeline: raw input text → parsed → bundle → file map.
// Used by the CLI, the MCP server and the web app.

import { buildBundle } from './core/build.ts';
import type { BatonBundle, BuildOptions, ParsedConversation } from './core/schema.ts';
import { slugify } from './core/util.ts';
import type { FileMap } from './core/zip.ts';
import { parseAny } from './parsers/detect.ts';
import { renderBundleFiles } from './render/files.ts';
import { buildSink, type SinkName, type SinkOptions } from './sinks/index.ts';

export interface ConvertOptions extends BuildOptions {
  url?: string;
  pick?: string; // conversation id or title substring, for multi-conversation exports
  sinks?: SinkName[];
  sinkOptions?: SinkOptions;
  keepSource?: boolean;
  skill?: boolean;
  html?: boolean;
}

export interface ConvertedBundle {
  slug: string;
  bundle: BatonBundle;
  files: FileMap;
}

export function pickConversations(list: ParsedConversation[], pick?: string): ParsedConversation[] {
  if (!pick) return list;
  const q = pick.toLowerCase();
  const hit = list.filter((c) => c.source.conversationId === pick || c.title.toLowerCase().includes(q));
  if (!hit.length) throw new Error(`No conversation matches --pick "${pick}". Available: ${list.slice(0, 20).map((c) => `"${c.title}"`).join(', ')}${list.length > 20 ? ', …' : ''}`);
  return hit;
}

export function convert(text: string, filename: string, opts: ConvertOptions = {}): ConvertedBundle[] {
  const parsed = pickConversations(parseAny(text, filename, opts.url), opts.pick);
  const used = new Set<string>();
  return parsed.map((p) => {
    const { bundle, extraFiles } = buildBundle(p, opts);
    const extra: FileMap = { ...extraFiles };
    for (const s of opts.sinks ?? []) extra[`sinks/${s}.json`] = JSON.stringify(buildSink(s, bundle, opts.sinkOptions), null, 2) + '\n';
    if (opts.keepSource) extra[`source/${filename.replace(/^.*[\\/]/, '') || 'input.txt'}`] = text;
    let slug = slugify(bundle.title);
    if (used.has(slug)) slug = `${slug}-${bundle.id.slice(0, 6)}`;
    used.add(slug);
    return { slug, bundle, files: renderBundleFiles(bundle, { extraFiles: extra, skill: opts.skill, html: opts.html }) };
  });
}

/** Choose the right member of an account-export ZIP (conversations.json), given decoded members. */
export function pickExportMember(names: string[]): string | undefined {
  const pref = names.filter((n) => /(^|\/)conversations\.json$/i.test(n));
  if (pref.length) return pref[0];
  return names.find((n) => /\.jsonl?$/i.test(n)) ?? names.find((n) => /\.html?$/i.test(n));
}

// Artifact recovery: rebuild the files an AI session created, from the code and tool calls it logged.
//
// Ops are extracted in event order and folded per path:
//   write/append  ← shell heredocs (`cat > f <<'EOF'`, `tee f <<EOF`), Claude Code Write
//   replace       ← Claude Code Edit / MultiEdit (applied exactly when the prior content is known)
//   touch         ← modifications we cannot replay statically (python open(p,'w'), sed -i, `> f`, cp/mv)
//   reference     ← files the conversation links to (sandbox:/mnt/data/...) but never shows the bytes of
// Result statuses: recovered (exact), stale (exact up to a later unreplayable change), lost.

import type { ArtifactStatus, BatonArtifact, BatonEvent, SourceKind } from '../core/schema.ts';
import { sha256Hex } from '../core/sha256.ts';
import { asString, isRecord } from '../core/util.ts';
import type { FileMap } from '../core/zip.ts';

export type FileOpKind = 'write' | 'append' | 'replace' | 'touch' | 'reference';

export interface FileOp {
  kind: FileOpKind;
  path: string; // absolute or original path as written in the source
  eventId: string;
  content?: string;
  old?: string;
  new?: string;
  all?: boolean;
  note?: string;
}

const IGNORED_PREFIXES = ['/tmp/', '/dev/', '/proc/', '/sys/', '/etc/', '/usr/', '/home/oai/', '/root/.'];
const IGNORED_PARTS = ['/node_modules/', '/.git/', '/__pycache__/'];

function ignorable(p: string): boolean {
  return IGNORED_PREFIXES.some((x) => p.startsWith(x)) || IGNORED_PARTS.some((x) => p.includes(x)) || p === '/dev/null';
}

function resolvePath(p: string, cwd: string): string {
  const unq = p.replace(/^['"]|['"]$/g, '');
  if (unq.startsWith('/')) return normaliseDots(unq);
  if (unq.startsWith('~')) return unq;
  return normaliseDots(`${cwd.replace(/\/$/, '')}/${unq}`);
}

function normaliseDots(p: string): string {
  const out: string[] = [];
  for (const seg of p.split('/')) {
    if (seg === '' || seg === '.') continue;
    if (seg === '..') out.pop();
    else out.push(seg);
  }
  return '/' + out.join('/');
}

// ───────────────────────────── shell scripts ─────────────────────────────

const HEREDOC_RE = /<<(-?)\s*(['"]?)([A-Za-z_][A-Za-z0-9_]*)\2/g;
const PATH_TOKEN = String.raw`(['"]?)([^\s'"<>|;&()]+)\1`;

/** Unwrap `bash -lc <script>` and JSON `{"cmd":["bash","-lc","..."]}` forms. */
export function unwrapShell(input: string): string {
  const t = input.trim();
  if (t.startsWith('{')) {
    try {
      const o = JSON.parse(t) as { cmd?: unknown };
      if (Array.isArray(o.cmd) && typeof o.cmd[o.cmd.length - 1] === 'string') return o.cmd[o.cmd.length - 1] as string;
    } catch {
      /* not JSON */
    }
  }
  return t.replace(/^(?:bash|sh)\s+-l?c\s+/, '');
}

function segmentAt(line: string, index: number): string {
  const seps = /&&|\|\||;|\|/g;
  let start = 0;
  let end = line.length;
  let m: RegExpExecArray | null;
  while ((m = seps.exec(line)) !== null) {
    if (m.index < index) start = m.index + m[0].length;
    else {
      end = m.index;
      break;
    }
  }
  return line.slice(start, end);
}

export function extractShellOps(input: string, eventId: string, initialCwd = '/'): FileOp[] {
  const script = unwrapShell(input);
  const lines = script.split('\n');
  const ops: FileOp[] = [];
  let cwd = initialCwd;
  const codeBodies: string[] = [];

  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    // `cd` changes the directory for the segments after it on the same line and for later lines.
    const lineCwd = cwd;
    const cds = [...line.matchAll(/(?:^|&&|;|\|\|)\s*cd\s+(['"]?)([^\s'";&|]+)\1/g)];
    const cwdAt = (idx: number): string => cds.reduce((c, m) => ((m.index ?? 0) < idx ? resolvePath(m[2], c) : c), lineCwd);

    const heredocs = [...line.matchAll(HEREDOC_RE)];
    // Modifications per command segment; heredoc segments (`cat > f <<'EOF'`) are writes, handled below.
    for (const seg of line.matchAll(/[^;&|]+/g)) {
      const start = seg.index ?? 0;
      const end = start + seg[0].length;
      if (heredocs.some((h) => (h.index ?? 0) >= start && (h.index ?? 0) < end)) continue;
      ops.push(...shellModifications(seg[0], eventId, cwdAt(start)));
    }
    cwd = cwdAt(line.length);

    let j = i + 1;
    for (const h of heredocs) {
      const strip = h[1] === '-';
      const quoted = h[2] !== '';
      const delim = h[3];
      const body: string[] = [];
      while (j < lines.length) {
        const raw = lines[j];
        const cmp = strip ? raw.replace(/^\t+/, '') : raw;
        j++;
        if (cmp === delim) break;
        body.push(strip ? cmp : raw);
      }
      const seg = segmentAt(line, h.index ?? 0);
      const catT = seg.match(new RegExp(String.raw`\bcat\b[^>]*?(>>?)\s*` + PATH_TOKEN));
      const teeT = seg.match(new RegExp(String.raw`\btee\s+(-a\s+)?` + PATH_TOKEN));
      const content = body.length ? body.join('\n') + '\n' : '';
      if (catT || teeT) {
        const append = catT ? catT[1] === '>>' : Boolean(teeT && teeT[1]);
        const path = resolvePath(catT ? catT[3] : (teeT as RegExpMatchArray)[3], cwdAt(h.index ?? 0));
        if (!ignorable(path)) {
          const expands = !quoted && /[$`\\]/.test(content);
          ops.push({ kind: append ? 'append' : 'write', path, eventId, content, note: expands ? 'unquoted heredoc: shell expansions ($VAR, `cmd`) were not evaluated' : undefined });
        }
      } else {
        // e.g. python - <<'PY' … PY: not a file, but its code may rewrite files.
        ops.push(...pythonModifications(content, eventId, cwdAt(h.index ?? 0)));
      }
    }
    i = j;
  }
  return ops;
}

function shellModifications(line: string, eventId: string, cwd: string): FileOp[] {
  const ops: FileOp[] = [];
  const add = (p: string, note: string) => {
    if (!/[./]/.test(p)) return; // not path-like (e.g. `x>0` inside an inline expression)
    const path = resolvePath(p, cwd);
    if (!ignorable(path) && !/^-/.test(p)) ops.push({ kind: 'touch', path, eventId, note });
  };
  // Output redirection (not 2>, &>, heredocs already stripped).
  for (const m of line.matchAll(new RegExp(String.raw`(?<![0-9&<>])(>>?)\s*` + PATH_TOKEN, 'g'))) add(m[3], m[1] === '>>' ? 'appended by shell redirect' : 'overwritten by shell redirect');
  for (const m of line.matchAll(new RegExp(String.raw`\bsed\s+-i\S*\s+(?:'[^']*'|"[^"]*"|\S+)\s+` + PATH_TOKEN, 'g'))) add(m[2], 'edited in place by sed -i');
  for (const m of line.matchAll(new RegExp(String.raw`\b(?:cp|mv)\s+(?:-\S+\s+)*\S+\s+` + PATH_TOKEN, 'g'))) add(m[2], 'replaced by cp/mv');
  for (const m of line.matchAll(new RegExp(String.raw`\bzip\s+(?:-\S+\s+)*` + PATH_TOKEN, 'g'))) add(m[2], 'archive produced by zip');
  return ops;
}

function pythonModifications(code: string, eventId: string, cwd: string): FileOp[] {
  const ops: FileOp[] = [];
  const vars = new Map<string, string>();
  for (const m of code.matchAll(/\b([A-Za-z_]\w*)\s*=\s*(?:Path\(\s*)?(['"])([^'"\n]+)\2/g)) {
    if (m[3].includes('/') || /\.\w{1,6}$/.test(m[3])) vars.set(m[1], m[3]);
  }
  const touch = (raw: string, note: string) => {
    const lit = raw.match(/^(['"])(.+)\1$/);
    const p = lit ? lit[2] : vars.get(raw);
    if (!p) return;
    const path = resolvePath(p, cwd);
    if (!ignorable(path)) ops.push({ kind: 'touch', path, eventId, note });
  };
  for (const m of code.matchAll(/open\(\s*([A-Za-z_]\w*|(['"])[^'"\n]+\2)\s*,\s*['"](?:w|a|wb|ab|w\+|a\+)['"]/g)) touch(m[1], 'rewritten by Python open(…, "w")');
  for (const m of code.matchAll(/\b([A-Za-z_]\w*)\.write_(?:text|bytes)\(/g)) touch(m[1], 'rewritten by Python write_text');
  for (const m of code.matchAll(/Path\(\s*((['"])[^'"\n]+\2)\s*\)\.write_(?:text|bytes)\(/g)) touch(m[1], 'rewritten by Python write_text');
  for (const m of code.matchAll(/\.(?:save|savefig|to_csv|to_json|to_excel|write_pdf)\(\s*([A-Za-z_]\w*|(['"])[^'"\n]+\2)/g)) touch(m[1], 'generated by Python (binary or derived output)');
  return ops;
}

// ───────────────────────────── structured tools (Claude Code) ─────────────────────────────

export function extractToolArgOps(name: string, args: Record<string, unknown>, eventId: string): FileOp[] {
  const path = asString(args.file_path || args.notebook_path || args.path);
  if (!path) return [];
  if (name === 'Write') return [{ kind: 'write', path, eventId, content: asString(args.content) }];
  if (name === 'Edit') return [{ kind: 'replace', path, eventId, old: asString(args.old_string), new: asString(args.new_string), all: args.replace_all === true }];
  if (name === 'MultiEdit' && Array.isArray(args.edits)) {
    return (args.edits as unknown[]).filter(isRecord).map((e) => ({ kind: 'replace' as const, path, eventId, old: asString(e.old_string), new: asString(e.new_string), all: e.replace_all === true }));
  }
  return [{ kind: 'touch', path, eventId, note: `modified by ${name}` }];
}

// ───────────────────────────── text references ─────────────────────────────

export function extractSandboxReferences(text: string, eventId: string): FileOp[] {
  const ops: FileOp[] = [];
  for (const m of text.matchAll(/sandbox:(\/mnt\/data\/[^\s)\]"'>`]+)/g)) {
    const p = m[1].replace(/[.,;:]+$/, '');
    if (!p.endsWith('/')) ops.push({ kind: 'reference', path: decodeURI(p), eventId });
  }
  return ops;
}

// ───────────────────────────── fold ─────────────────────────────

export interface RecoveryResult {
  artifacts: BatonArtifact[];
  replay?: FileMap;
}

export function bundlePath(original: string, kind: SourceKind, cwd?: string): string {
  let p = original.replace(/^sandbox:/, '');
  if (p.startsWith('/mnt/data/')) p = p.slice('/mnt/data/'.length);
  else if (cwd && p.startsWith(cwd.replace(/\/$/, '') + '/')) p = p.slice(cwd.replace(/\/$/, '').length + 1);
  else if (p.startsWith('/')) p = '_abs' + p;
  // Never allow escaping the bundle directory.
  const safe = p.split('/').filter((s) => s && s !== '.' && s !== '..').join('/');
  return safe || (kind === 'unknown' ? 'file' : 'unnamed');
}

const BINARY_EXT = /\.(pdf|docx?|xlsx?|pptx?|zip|png|jpe?g|gif|webp|svg|mp4|mov|wav|mp3|pkl|npy|npz|parquet|sqlite|db)$/i;

export function collectOps(events: BatonEvent[], kind: SourceKind, cwd?: string): FileOp[] {
  const ops: FileOp[] = [];
  for (const e of events) {
    if (e.kind === 'tool_call' && e.tool) {
      const { name, input, args } = e.tool;
      if (args && isRecord(args)) ops.push(...extractToolArgOps(name, args, e.id));
      else if (input && (name === 'container.exec' || name === 'python' || name === 'Bash' || e.tool.language === 'bash')) {
        ops.push(...extractShellOps(input, e.id, kind === 'claude-code' && cwd ? cwd : '/'));
      }
    }
    if ((kind === 'chatgpt-share' || kind === 'chatgpt-export') && (e.kind === 'message' || e.kind === 'tool_call')) {
      ops.push(...extractSandboxReferences(e.text, e.id));
    }
  }
  return ops;
}

export function foldOps(ops: FileOp[], kind: SourceKind, cwd?: string): BatonArtifact[] {
  interface S { original: string; content?: string; versions: number; status: ArtifactStatus; from: string[]; modified: string[]; notes: Set<string> }
  const state = new Map<string, S>();
  const get = (p: string): S => {
    let s = state.get(p);
    if (!s) {
      s = { original: p, versions: 0, status: 'lost', from: [], modified: [], notes: new Set() };
      state.set(p, s);
    }
    return s;
  };

  for (const op of ops) {
    const s = get(op.path);
    switch (op.kind) {
      case 'write':
        s.content = op.content ?? '';
        s.versions++;
        s.status = 'recovered';
        s.from.push(op.eventId);
        s.modified = [];
        s.notes.clear();
        if (op.note) s.notes.add(op.note);
        break;
      case 'append':
        if (s.content !== undefined) {
          s.content += op.content ?? '';
          s.versions++;
          s.from.push(op.eventId);
        } else {
          s.content = op.content ?? '';
          s.status = 'stale';
          s.notes.add('appended to a file whose earlier content is not in the source');
          s.from.push(op.eventId);
        }
        break;
      case 'replace':
        if (s.content !== undefined && op.old !== undefined && s.content.includes(op.old)) {
          s.content = op.all ? s.content.split(op.old).join(op.new ?? '') : s.content.replace(op.old, () => op.new ?? '');
          s.versions++;
          s.from.push(op.eventId);
        } else {
          if (s.content === undefined) s.notes.add(kind === 'claude-code' ? 'pre-existing file edited during the session; only the edit hunks are in the transcript' : 'edit target content unknown');
          else s.notes.add('an edit did not match the reconstructed content');
          s.status = s.content === undefined ? 'lost' : 'stale';
          s.modified.push(op.eventId);
        }
        break;
      case 'touch':
        if (s.content !== undefined) s.status = 'stale';
        s.modified.push(op.eventId);
        if (op.note) s.notes.add(op.note);
        break;
      case 'reference':
        break;
    }
  }

  const artifacts: BatonArtifact[] = [];
  for (const [p, s] of state) {
    if (s.content === undefined) {
      if (kind === 'chatgpt-share' || kind === 'chatgpt-export') {
        s.notes.add(BINARY_EXT.test(p) ? 'binary/derived output; regenerate with replay/' : 'created by code the source did not include');
      } else {
        s.notes.add('exists in the original working directory; contents not reconstructable from the log');
      }
    }
    artifacts.push({
      path: bundlePath(p, kind, cwd),
      originalPath: s.original,
      status: s.content === undefined ? 'lost' : s.status,
      content: s.content,
      bytes: s.content === undefined ? undefined : new TextEncoder().encode(s.content).length,
      sha256: s.content === undefined ? undefined : sha256Hex(s.content),
      versions: s.versions || undefined,
      recoveredFrom: s.from.length ? s.from : undefined,
      modifiedBy: s.modified.length ? s.modified : undefined,
      note: s.notes.size ? [...s.notes].join('; ') : undefined,
    });
  }
  return artifacts.sort((a, b) => a.path.localeCompare(b.path));
}

export function recoverArtifacts(events: BatonEvent[], kind: SourceKind, cwd?: string): RecoveryResult {
  const artifacts = foldOps(collectOps(events, kind, cwd), kind, cwd);
  // De-duplicate bundle paths (two originals could map to the same safe path).
  const seen = new Map<string, number>();
  for (const a of artifacts) {
    const n = seen.get(a.path) ?? 0;
    seen.set(a.path, n + 1);
    if (n) a.path = a.path.replace(/(\.[^./]+)?$/, `~${n}$1`);
  }
  return { artifacts, replay: buildReplay(events) };
}

// ───────────────────────────── replay kit ─────────────────────────────

export function buildReplay(events: BatonEvent[]): FileMap | undefined {
  const cells = events.filter((e) => e.kind === 'tool_call' && e.tool?.name === 'container.exec' && e.tool.input);
  if (!cells.length) return undefined;
  const files: FileMap = {};
  cells.forEach((e, i) => {
    const n = String(i + 1).padStart(3, '0');
    files[`replay/cells/${n}.sh`] = `# Cell ${n} · source event ${e.id}${e.time ? ' · ' + e.time : ''}\n# ${e.tool?.title ?? ''}\n${unwrapShell(e.tool!.input!)}\n`;
  });
  files['replay/run-in-docker.sh'] = REPLAY_SH;
  files['replay/README.md'] = replayReadme(cells.length);
  return files;
}

const REPLAY_SH = `#!/usr/bin/env bash
# Re-run the code cells captured from the source conversation, in order, inside ONE throwaway container.
# The cells expect the ChatGPT sandbox layout, so the work dir is mounted at /mnt/data.
#
#   REVIEW cells/*.sh FIRST. They are third-party code captured from another AI's sandbox.
#
# Usage: ./run-in-docker.sh [workdir]
#   BATON_REPLAY_IMAGE    container image (default python:3.12-slim)
#   BATON_REPLAY_SETUP    shell run before the cells, e.g. "pip install numpy matplotlib python-docx"
#   BATON_REPLAY_NETWORK  docker network (default none; set to "bridge" if setup needs to download)
set -uo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
WORK="$(mkdir -p "\${1:-$HERE/workdir}" && cd "\${1:-$HERE/workdir}" && pwd)"
IMAGE="\${BATON_REPLAY_IMAGE:-python:3.12-slim}"
NET="\${BATON_REPLAY_NETWORK:-none}"
SETUP="\${BATON_REPLAY_SETUP:-true}"
exec docker run --rm --network "$NET" -v "$WORK:/mnt/data" -v "$HERE/cells:/cells:ro" -w /mnt/data "$IMAGE" \\
  bash -c "$SETUP; for c in /cells/*.sh; do echo \\"── \\$(basename \\$c)\\"; bash \\"\\$c\\" || echo '   (cell failed, continuing)'; done"
`;

function replayReadme(n: number): string {
  return `# Replay kit

The source conversation ran **${n} code cell(s)** in its own sandbox. The source did not include their
outputs: tool results were redacted, and files could not be downloaded. These cells are the exact code that ran, in order.
Re-running them in a sandbox you control can regenerate derived outputs such as PDFs, figures and archives.

\`\`\`bash
# 1. Read every cell first. This is third-party code.
ls cells/ && less cells/*.sh
# 2. Run in an isolated container (no network by default)
BATON_REPLAY_NETWORK=bridge BATON_REPLAY_SETUP="pip install numpy matplotlib python-docx reportlab pypdf" ./run-in-docker.sh
# 3. Outputs land in ./workdir (mounted at /mnt/data inside the container)
\`\`\`

Known limits:
- Cells that call vendor-internal helpers (for example \`/home/oai/skills/...\`) will fail outside the vendor sandbox.
- Cells whose input the source blanked (for example ChatGPT \`functions.exec\`) are not here. Files they made are listed as **lost** in \`LOSS_AUDIT.md\`.
- Baton never runs these cells itself.
`;
}

// Relay records: checkpoints written by models from inside an AI, plus bundles captured by the extension/CLI.
// A record renders to a normal Baton bundle, so every surface (HANDOFF.md, viewer, sinks) works unchanged.

import { buildBundle } from '../core/build.ts';
import type { BatonBundle, BatonEvent, CapturedFile, ParsedConversation } from '../core/schema.ts';
import type { FileMap } from '../core/zip.ts';
import { renderBundleFiles } from '../render/files.ts';

export interface CheckpointFile {
  path: string;
  content: string;
  encoding?: 'utf8' | 'base64';
}

export interface ToolOutput {
  tool: string;
  input?: string;
  output: string;
}

/** What a model writes when it checkpoints its work. Everything except `state` is optional. */
export interface Checkpoint {
  seq: number;
  at: string;
  from: string; // MCP client name (e.g. "ChatGPT", "claude-ai", "cursor") or "extension"/"cli"
  title?: string;
  goal?: string;
  state: string; // where the work stands, in the model's words
  decisions?: string[];
  next_steps?: string[];
  open_questions?: string[];
  user_prompts?: string[]; // verbatim prompts the model can see in its context
  files?: CheckpointFile[];
  tool_outputs?: ToolOutput[];
  notes?: string;
}

export interface SealedPayload {
  iv: string; // base64
  data: string; // base64 AES-GCM ciphertext
  alg: 'AES-GCM-256';
}

export interface RelayRecord {
  code: string;
  title: string;
  createdAt: string;
  updatedAt: string;
  expiresAt: string;
  from: string[]; // surfaces that contributed
  bundle?: BatonBundle; // captured bundle (extension, CLI)
  checkpoints: Checkpoint[];
  sealed?: SealedPayload; // end-to-end encrypted bundle (server cannot read)
}

type Draft = Omit<BatonEvent, 'seq' | 'hash'>;

function bullets(title: string, items?: string[]): string {
  return items && items.length ? `**${title}**\n${items.map((i) => `- ${i}`).join('\n')}\n` : '';
}

export function checkpointToEvents(c: Checkpoint, seenPrompts: Set<string>): { events: Draft[]; files: CapturedFile[] } {
  const events: Draft[] = [];
  const id = `cp${c.seq}`;
  events.push({ id: `${id}-note`, kind: 'note', role: 'assistant', time: c.at, text: `Checkpoint ${c.seq} from ${c.from}` });
  (c.user_prompts ?? []).forEach((p, i) => {
    const key = p.trim();
    if (!key || seenPrompts.has(key)) return;
    seenPrompts.add(key);
    events.push({ id: `${id}-u${i + 1}`, kind: 'message', role: 'user', time: c.at, text: p, meta: { recalledBy: c.from } });
  });
  const body = [
    c.goal ? `**Goal.** ${c.goal}\n` : '',
    `**State.** ${c.state}\n`,
    bullets('Decisions', c.decisions),
    bullets('Next steps', c.next_steps),
    bullets('Open questions', c.open_questions),
    c.notes ? `**Notes.** ${c.notes}\n` : '',
  ]
    .filter(Boolean)
    .join('\n');
  events.push({ id: `${id}-state`, kind: 'message', role: 'assistant', time: c.at, text: body, meta: { checkpoint: c.seq, from: c.from } });
  (c.tool_outputs ?? []).forEach((t, i) => {
    events.push({ id: `${id}-t${i + 1}`, kind: 'tool_call', role: 'assistant', time: c.at, text: t.tool, tool: { name: t.tool, input: t.input } });
    events.push({ id: `${id}-r${i + 1}`, kind: 'tool_result', role: 'tool', time: c.at, text: t.output, tool: { name: t.tool } });
  });
  const files: CapturedFile[] = (c.files ?? []).map((f) => ({ path: f.path, content: f.content, encoding: f.encoding, eventId: `${id}-state`, note: `written by the model at checkpoint ${c.seq} (${c.from})` }));
  return { events, files };
}

/** Re-open a stored bundle as a parsed conversation so checkpoints can extend it. */
export function bundleToParsed(b: BatonBundle): ParsedConversation {
  return {
    title: b.title,
    source: b.source,
    events: b.events.map(({ seq: _s, hash: _h, ...e }) => e),
    capturedFiles: b.artifacts
      .filter((a) => a.content !== undefined)
      .map((a) => ({ path: a.originalPath, content: a.content!, encoding: a.encoding, mimeType: a.mimeType, note: a.note })),
    loss: b.loss.filter((l) => !['files-recovered', 'files-lost', 'files-stale', 'tool-outputs', 'tool-inputs', 'baton-redactions', 'private-context'].includes(l.category)),
    sourceLinks: b.links,
  };
}

export function recordToParsed(r: RelayRecord): ParsedConversation {
  const base: ParsedConversation = r.bundle
    ? bundleToParsed(r.bundle)
    : { title: r.title, source: { kind: 'baton-relay', tool: r.from.join(' + ') || 'Baton relay', conversationId: r.code, createdAt: r.createdAt, updatedAt: r.updatedAt }, events: [], capturedFiles: [] };
  const seen = new Set(base.events.filter((e) => e.kind === 'message' && e.role === 'user').map((e) => e.text.trim()));
  for (const c of r.checkpoints) {
    const { events, files } = checkpointToEvents(c, seen);
    base.events.push(...events);
    base.capturedFiles = [...(base.capturedFiles ?? []), ...files];
  }
  const goal = [...r.checkpoints].reverse().find((c) => c.goal)?.goal;
  if (!base.events.some((e) => e.kind === 'message' && e.role === 'user') && goal) {
    base.events.unshift({ id: 'goal', kind: 'message', role: 'user', text: goal, meta: { recalledBy: 'checkpoint goal' } });
  }
  if (r.checkpoints.length) {
    base.loss = [
      ...(base.loss ?? []),
      { category: 'model-reported', count: r.checkpoints.length, severity: 'info', detail: `${r.checkpoints.length} checkpoint(s) were written by the model from inside ${[...new Set(r.checkpoints.map((c) => c.from))].join(', ')}. They reflect what the model held in context. Prompts marked "recalled" are the model's copy of them.` },
    ];
  }
  base.title = r.title || base.title;
  return base;
}

export function renderRecord(r: RelayRecord, now?: string): { bundle: BatonBundle; files: FileMap } {
  const { bundle, extraFiles } = buildBundle(recordToParsed(r), { now: now ?? r.updatedAt });
  return { bundle, files: renderBundleFiles(bundle, { extraFiles }) };
}

// Send bundles to / pick up handoffs from a relay (remote URL) or the local store (~/.baton/store).

import type { BatonBundle } from '../core/schema.ts';
import { base64ToBytes, bytesToBase64 } from '../core/util.ts';
import { unzipStored, zip, type FileMap } from '../core/zip.ts';
import { renderBundleFiles } from '../render/files.ts';
import type { RelayRecord } from './checkpoint.ts';
import { renderRecord } from './checkpoint.ts';
import { parsePickup, seal, unseal } from './seal.ts';
import { RelayStore } from './store.ts';

export interface SendResult {
  code: string;
  link: string; // includes #key when sealed
  sealed: boolean;
  expiresAt?: string;
}

export function sealedPlaintext(bundle: BatonBundle, files: FileMap): Uint8Array {
  const prefixed: FileMap = {};
  for (const [k, v] of Object.entries(files)) prefixed[`${bundle.id}/${k}`] = v;
  return new TextEncoder().encode(JSON.stringify({ title: bundle.title, handoff: String(files['HANDOFF.md']), prompt: String(files['PROMPT.md']), zip: bytesToBase64(zip(prefixed)) }));
}

export async function sendBundle(bundle: BatonBundle, files: FileMap, opts: { relay?: string; token?: string; sealed?: boolean; from?: string; store?: RelayStore }): Promise<SendResult> {
  let body: Record<string, unknown> = { bundle, from: opts.from ?? 'cli' };
  let key: string | undefined;
  if (opts.sealed) {
    const s = await seal(sealedPlaintext(bundle, files));
    body = { sealed: s.sealed, title: bundle.title, from: opts.from ?? 'cli' };
    key = s.key;
  }
  if (!opts.relay) {
    const store = opts.store ?? new RelayStore();
    const rec = store.create({ title: bundle.title, from: String(body.from), bundle: body.bundle as BatonBundle | undefined, sealed: body.sealed as RelayRecord['sealed'] });
    return { code: rec.code, link: key ? `${rec.code}#${key}` : rec.code, sealed: !!key, expiresAt: rec.expiresAt };
  }
  const res = await fetch(opts.relay.replace(/\/$/, '') + '/api/handoffs', {
    method: 'POST',
    headers: { 'content-type': 'application/json', ...(opts.token ? { authorization: `Bearer ${opts.token}` } : {}) },
    body: JSON.stringify(body),
  });
  const out = (await res.json()) as { code?: string; url?: string; expiresAt?: string; error?: string };
  if (!res.ok || !out.code) throw new Error(`Relay refused the upload: ${out.error ?? res.status}`);
  const base = out.url?.startsWith('http') ? out.url : `${opts.relay.replace(/\/$/, '')}/h/${out.code}`;
  return { code: out.code, link: key ? `${base}#${key}` : base, sealed: !!key, expiresAt: out.expiresAt };
}

/** Fetch a handoff and render it to bundle files. Accepts "BTN-…", "BTN-…#key" or a full /h/ link. */
export async function pickup(input: string, opts: { relay?: string; store?: RelayStore } = {}): Promise<{ code: string; files: FileMap; title: string }> {
  const p = parsePickup(input);
  const relay = p.base ?? opts.relay;
  let rec: RelayRecord | undefined;
  if (relay) {
    const res = await fetch(`${relay.replace(/\/$/, '')}/api/handoffs/${encodeURIComponent(p.code)}`);
    if (res.status === 404) throw new Error(`No handoff ${p.code} on ${relay} (expired or wrong code)`);
    if (!res.ok) throw new Error(`Relay answered HTTP ${res.status}`);
    rec = (await res.json()) as RelayRecord;
  } else {
    rec = (opts.store ?? new RelayStore()).get(p.code);
    if (!rec) throw new Error(`No handoff ${p.code} in the local store. Pass --relay <url> if it was sent to a remote relay.`);
  }
  if (rec.sealed && !rec.bundle) {
    if (!p.key) throw new Error('This handoff is end-to-end encrypted: use the full code including "#key".');
    const payload = JSON.parse(new TextDecoder().decode(await unseal(rec.sealed, p.key))) as { title: string; zip: string };
    const members = unzipStored(base64ToBytes(payload.zip));
    const files: FileMap = {};
    for (const [k, v] of Object.entries(members)) files[k.replace(/^[^/]+\//, '')] = k.endsWith('.md') || k.endsWith('.json') || k.endsWith('.html') ? new TextDecoder().decode(v) : v;
    return { code: rec.code, files, title: payload.title };
  }
  const { files, bundle } = renderRecord(rec);
  return { code: rec.code, files, title: bundle.title };
}

export { renderBundleFiles };

// End-to-end sealing for relay uploads (extension / CLI): AES-GCM-256 via WebCrypto (Node ≥18 and browsers).
// The key travels only in the pickup link's #fragment, which browsers never send to the server.

import type { SealedPayload } from './checkpoint.ts';
import { base64ToBytes, bytesToBase64 } from '../core/util.ts';

const subtle = () => globalThis.crypto.subtle;

const b64url = (b: Uint8Array) => bytesToBase64(b).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const fromB64url = (s: string) => base64ToBytes(s.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((s.length + 3) % 4));

export async function seal(plaintext: Uint8Array): Promise<{ sealed: SealedPayload; key: string }> {
  const raw = new Uint8Array(32);
  globalThis.crypto.getRandomValues(raw);
  const iv = new Uint8Array(12);
  globalThis.crypto.getRandomValues(iv);
  const key = await subtle().importKey('raw', raw, 'AES-GCM', false, ['encrypt']);
  const ct = new Uint8Array(await subtle().encrypt({ name: 'AES-GCM', iv }, key, plaintext as BufferSource));
  return { sealed: { iv: bytesToBase64(iv), data: bytesToBase64(ct), alg: 'AES-GCM-256' }, key: b64url(raw) };
}

export async function unseal(sealed: SealedPayload, keyB64url: string): Promise<Uint8Array> {
  const key = await subtle().importKey('raw', fromB64url(keyB64url) as BufferSource, 'AES-GCM', false, ['decrypt']);
  try {
    return new Uint8Array(await subtle().decrypt({ name: 'AES-GCM', iv: base64ToBytes(sealed.iv) as BufferSource }, key, base64ToBytes(sealed.data) as BufferSource));
  } catch {
    throw new Error('Could not decrypt: wrong key or tampered data');
  }
}

/** "BTN-XXXX-XXXX-XXXX#key" or a full https://…/h/BTN-…#key link → {code, key?, base?} */
export function parsePickup(input: string): { code: string; key?: string; base?: string } {
  const [left, key] = input.trim().split('#');
  const m = left.match(/^(https?:\/\/.+?)\/h\/(BTN-[0-9A-Z-]+)/i);
  if (m) return { base: m[1], code: m[2].toUpperCase(), key: key || undefined };
  return { code: left.toUpperCase(), key: key || undefined };
}

// Baton relay hub: one small zero-dependency HTTP server that embeds Baton in web AIs.
//
//   POST /mcp[/<secret>]          MCP over Streamable HTTP (JSON responses): baton_checkpoint, baton_pickup, baton_get_file
//   POST /api/handoffs            upload a captured bundle {bundle} or an end-to-end sealed one {sealed, title}
//   GET  /api/handoffs/<code>     record as JSON (sealed payloads stay opaque)
//   POST /api/handoffs/<code>/checkpoints   append a checkpoint (same fields as the MCP tool)
//   GET  /h/<code>                human viewer (sealed: decrypts in the browser with the #key)
//   GET  /h/<code>.zip            bundle as a zip
//   GET  /healthz
//
// Env: PORT, BATON_STORE, BATON_PUBLIC_URL, BATON_RELAY_TOKEN (bearer for REST writes),
//      BATON_MCP_SECRET (serve MCP only at /mcp/<secret>), BATON_TTL_DAYS, BATON_MAX_BYTES.

import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import type { BatonBundle } from '../core/schema.ts';
import { VERSION } from '../core/schema.ts';
import { escapeHtml } from '../core/util.ts';
import { zip } from '../core/zip.ts';
import { handleRpc, type McpSession } from '../mcp/protocol.ts';
import { renderRecord, type SealedPayload } from './checkpoint.ts';
import { CODE_RE, normaliseCode, RelayStore } from './store.ts';
import { RELAY_INSTRUCTIONS, relayTools } from './tools.ts';

export interface RelayServerOptions {
  port?: number;
  host?: string;
  store?: RelayStore;
  publicUrl?: string;
  token?: string;
  mcpSecret?: string;
  rateLimitPerMinute?: number;
  log?: (msg: string) => void;
}

export function createRelayServer(o: RelayServerOptions = {}) {
  const store = o.store ?? new RelayStore();
  const publicUrl = o.publicUrl ?? process.env.BATON_PUBLIC_URL;
  const token = o.token ?? process.env.BATON_RELAY_TOKEN;
  const mcpSecret = o.mcpSecret ?? process.env.BATON_MCP_SECRET;
  const mcpPath = mcpSecret ? `/mcp/${mcpSecret}` : '/mcp';
  const tools = relayTools(store, { publicUrl });
  const info = { name: 'baton-relay', version: VERSION, instructions: RELAY_INSTRUCTIONS };
  const sessions = new Map<string, McpSession>();
  const hits = new Map<string, { n: number; t: number }>();
  const limit = o.rateLimitPerMinute ?? 120;
  const log = o.log ?? (() => {});

  const send = (res: ServerResponse, status: number, body: string | Uint8Array, type = 'application/json', extra: Record<string, string> = {}) => {
    res.writeHead(status, { 'content-type': type, 'access-control-allow-origin': '*', 'access-control-allow-headers': 'content-type, authorization, mcp-session-id, mcp-protocol-version', 'access-control-expose-headers': 'mcp-session-id', 'x-content-type-options': 'nosniff', ...extra });
    res.end(body);
  };
  const json = (res: ServerResponse, status: number, v: unknown, extra: Record<string, string> = {}) => send(res, status, JSON.stringify(v), 'application/json', extra);

  const readBody = (req: IncomingMessage): Promise<string> =>
    new Promise((resolve, reject) => {
      const chunks: Buffer[] = [];
      let size = 0;
      req.on('data', (c: Buffer) => {
        size += c.length;
        if (size > store.maxBytes + 1024 * 1024) {
          reject(new Error('Request too large'));
          req.destroy();
        } else chunks.push(c);
      });
      req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
      req.on('error', reject);
    });

  const authorized = (req: IncomingMessage) => !token || req.headers.authorization === `Bearer ${token}`;

  const server = createServer(async (req, res) => {
    const url = new URL(req.url ?? '/', 'http://relay.local');
    const ip = String(req.headers['x-forwarded-for'] ?? req.socket.remoteAddress ?? '').split(',')[0].trim();
    const now = Date.now();
    const h = hits.get(ip);
    if (!h || now - h.t > 60000) hits.set(ip, { n: 1, t: now });
    else if (++h.n > limit) return json(res, 429, { error: 'Too many requests' });

    try {
      if (req.method === 'OPTIONS') return send(res, 204, '');
      if (url.pathname === '/healthz') return json(res, 200, { ok: true, version: VERSION });

      // ── MCP (Streamable HTTP, JSON response mode) ──
      if (url.pathname === mcpPath) {
        if (req.method === 'GET') return json(res, 405, { error: 'This server does not offer an SSE stream; POST JSON-RPC instead.' }, { allow: 'POST, DELETE' });
        if (req.method === 'DELETE') {
          sessions.delete(String(req.headers['mcp-session-id'] ?? ''));
          return send(res, 200, '');
        }
        if (req.method !== 'POST') return json(res, 405, { error: 'POST only' });
        const body = JSON.parse(await readBody(req)) as Record<string, unknown> | Record<string, unknown>[];
        let sid = String(req.headers['mcp-session-id'] ?? '');
        let session = sessions.get(sid);
        const msgs = Array.isArray(body) ? body : [body];
        if (!session) {
          session = { clientName: String(req.headers['x-baton-client'] ?? req.headers['user-agent'] ?? 'mcp-client').slice(0, 60) };
          if (msgs.some((m) => m.method === 'initialize')) {
            sid = randomUUID();
            sessions.set(sid, session);
          }
        }
        const out = (await Promise.all(msgs.map((m) => handleRpc(m, tools, info, session!)))).filter(Boolean);
        const headers: Record<string, string> = sid && sessions.has(sid) ? { 'mcp-session-id': sid } : {};
        if (!out.length) return send(res, 202, '', 'application/json', headers);
        log(`mcp ${msgs.map((m) => (m.method === 'tools/call' ? `tools/call:${(m.params as { name?: string })?.name}` : m.method)).join(',')} from ${session.clientName}`);
        return json(res, 200, Array.isArray(body) ? out : out[0], headers);
      }

      // ── REST ──
      if (url.pathname === '/api/handoffs' && req.method === 'POST') {
        if (!authorized(req)) return json(res, 401, { error: 'Bearer token required' });
        const b = JSON.parse(await readBody(req)) as { bundle?: BatonBundle; sealed?: SealedPayload; title?: string; from?: string };
        if (!b.bundle && !b.sealed) return json(res, 400, { error: 'Send {bundle} or {sealed}' });
        if (b.bundle && b.bundle.schema !== 'baton.bundle/v1') return json(res, 400, { error: 'Unsupported bundle schema' });
        const rec = store.create({ title: b.title ?? b.bundle?.title, from: b.from ?? 'api', bundle: b.bundle, sealed: b.sealed });
        log(`upload ${rec.code} ${b.sealed ? '(sealed)' : ''}`);
        return json(res, 201, { code: rec.code, expiresAt: rec.expiresAt, url: publicUrl ? `${publicUrl.replace(/\/$/, '')}/h/${rec.code}` : `/h/${rec.code}` });
      }
      const api = url.pathname.match(/^\/api\/handoffs\/([^/]+)(\/checkpoints)?$/);
      if (api) {
        const code = normaliseCode(decodeURIComponent(api[1]));
        if (!CODE_RE.test(code)) return json(res, 400, { error: 'Invalid code' });
        if (api[2] && req.method === 'POST') {
          if (!authorized(req)) return json(res, 401, { error: 'Bearer token required' });
          const cp = JSON.parse(await readBody(req)) as Record<string, unknown>;
          const tool = tools.find((t) => t.name === 'baton_checkpoint')!;
          const text = await tool.run({ ...cp, handoff: code }, { clientName: String(cp.from ?? 'api') });
          return json(res, 200, { ok: true, message: text });
        }
        const rec = store.get(code);
        if (!rec) return json(res, 404, { error: 'Not found or expired' });
        return json(res, 200, rec);
      }

      // ── Viewer ──
      const view = url.pathname.match(/^\/h\/([^/.]+)(\.zip)?$/);
      if (view && req.method === 'GET') {
        const rec = store.get(decodeURIComponent(view[1]));
        if (!rec) return send(res, 404, page('Not found', '<p>This handoff does not exist or has expired.</p>'), 'text/html; charset=utf-8');
        if (rec.sealed && !rec.bundle) {
          if (view[2]) return json(res, 400, { error: 'Sealed handoffs are decrypted in the browser; open /h/<code>#<key>' });
          return send(res, 200, sealedPage(rec.code, rec.title), 'text/html; charset=utf-8', { 'cache-control': 'no-store', 'referrer-policy': 'no-referrer' });
        }
        const { files } = renderRecord(rec);
        if (view[2]) {
          const prefixed: Record<string, string | Uint8Array> = {};
          for (const [k, v] of Object.entries(files)) prefixed[`${rec.code}/${k}`] = v;
          return send(res, 200, zip(prefixed), 'application/zip', { 'content-disposition': `attachment; filename="${rec.code}.baton.zip"` });
        }
        return send(res, 200, String(files['index.html']), 'text/html; charset=utf-8', { 'content-security-policy': "default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; img-src data:", 'referrer-policy': 'no-referrer' });
      }

      if (url.pathname === '/' && req.method === 'GET') {
        const base = publicUrl ?? `http://${req.headers.host}`;
        return send(res, 200, page('Baton relay', landing(base, mcpPath)), 'text/html; charset=utf-8');
      }
      return json(res, 404, { error: 'Not found' });
    } catch (err) {
      return json(res, 400, { error: err instanceof Error ? err.message : String(err) });
    }
  });

  const timer = setInterval(() => store.purgeExpired(), 3600000);
  timer.unref();
  server.on('close', () => clearInterval(timer));
  return { server, store, mcpPath };
}

function page(title: string, body: string): string {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(title)}</title>
<style>:root{--bg:#f3f5f4;--fg:#14201b;--mu:#5b6b64;--ac:#2343c9;--line:#d7dfdb}@media (prefers-color-scheme:dark){:root{--bg:#0f1513;--fg:#e4ebe7;--mu:#9aaba3;--ac:#8ea4ff;--line:#2a3632}}
body{background:var(--bg);color:var(--fg);font:16px/1.55 system-ui,sans-serif;max-width:760px;margin:0 auto;padding:32px 16px}h1{font-size:34px;margin:0 0 8px}code,pre{font:13px ui-monospace,monospace}pre{background:color-mix(in srgb,var(--fg) 6%,transparent);padding:12px;border-radius:6px;overflow:auto;white-space:pre-wrap}a{color:var(--ac)}.mu{color:var(--mu)}button{font:inherit;padding:8px 14px;border-radius:6px;border:1px solid var(--fg);background:none;color:var(--fg);cursor:pointer}</style></head><body>${body}</body></html>`;
}

function landing(base: string, mcpPath: string): string {
  const mcp = base.replace(/\/$/, '') + mcpPath;
  return `<h1>Baton relay</h1><p class="mu">Hands AI work from one assistant to another, with prompts, files, tool outputs and decisions, from inside the assistants.</p>
<h2>Add it to an AI</h2>
<p><b>MCP server URL:</b></p><pre>${escapeHtml(mcp)}</pre>
<ul><li><b>ChatGPT</b>: Settings → Apps &amp; Connectors → Advanced → Developer mode → Create, paste the URL, authentication "No authentication".</li>
<li><b>Claude</b> (web/desktop): Settings → Connectors → Add custom connector → paste the URL.</li>
<li><b>Claude Code</b>: <code>claude mcp add --transport http baton ${escapeHtml(mcp)}</code></li>
<li><b>Cursor / Codex / Gemini CLI</b>: add an HTTP MCP server with this URL.</li></ul>
<h2>Use it</h2><p>In any AI: <i>"baton: hand this off"</i> → you get a code like <code>BTN-7F3K-9QXA-2M4P</code>. In another AI: <i>"baton pickup BTN-7F3K-9QXA-2M4P"</i>. Or open <code>${escapeHtml(base)}/h/&lt;code&gt;</code>.</p>`;
}

function sealedPage(code: string, title: string): string {
  return page(
    `Baton · ${title}`,
    `<h1>${escapeHtml(title)}</h1><p class="mu">End-to-end encrypted handoff <code>${escapeHtml(code)}</code>. It is decrypted here in your browser. The server never had the key.</p>
<div id="out"><p>Decrypting…</p></div>
<script>(async()=>{const out=document.getElementById('out');const key=location.hash.slice(1);if(!key){out.innerHTML='<p>This link is missing its #key part. Ask the sender for the full link.</p>';return}
try{const r=await fetch('/api/handoffs/${code}');const rec=await r.json();const b=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));const kb=b(key.replace(/-/g,'+').replace(/_/g,'/')+'==='.slice((key.length+3)%4));
const k=await crypto.subtle.importKey('raw',kb,'AES-GCM',false,['decrypt']);const pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:b(rec.sealed.iv)},k,b(rec.sealed.data));
const p=JSON.parse(new TextDecoder().decode(pt));const esc=s=>s.replace(/&/g,'&amp;').replace(/</g,'&lt;');
out.innerHTML='<p><button id="cp">Copy paste-ready prompt</button> <button id="dl">Download bundle (.zip)</button></p><h2>HANDOFF.md</h2><pre>'+esc(p.handoff)+'</pre>';
document.getElementById('cp').onclick=()=>navigator.clipboard.writeText(p.prompt);
document.getElementById('dl').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([b(p.zip)],{type:'application/zip'}));a.download='${code}.baton.zip';a.click()};
}catch(e){out.innerHTML='<p>Could not decrypt this handoff (wrong key or damaged data).</p>'}})();</script>`,
  );
}

export function startRelay(o: RelayServerOptions = {}): Promise<{ url: string; close: () => Promise<void> }> {
  const { server, mcpPath } = createRelayServer(o);
  const port = o.port ?? Number(process.env.PORT ?? 8787);
  return new Promise((resolve) => {
    server.listen(port, o.host ?? '0.0.0.0', () => {
      const addr = server.address();
      const actual = typeof addr === 'object' && addr ? addr.port : port;
      const url = `http://localhost:${actual}`;
      (o.log ?? console.error)(`Baton relay ${VERSION} listening on ${url} · MCP at ${url}${mcpPath}`);
      resolve({ url, close: () => new Promise((r) => server.close(() => r())) });
    });
  });
}

// File-backed relay store. One JSON file per handoff, written atomically. Codes are capability tokens.

import { existsSync, mkdirSync, readdirSync, readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';
import type { BatonBundle } from '../core/schema.ts';
import type { Checkpoint, RelayRecord, SealedPayload } from './checkpoint.ts';

const ALPHABET = '0123456789ABCDEFGHJKMNPQRSTVWXYZ'; // Crockford base32 (no I, L, O, U)
export const CODE_RE = /^BTN(?:-[0-9A-HJKMNP-TV-Z]{4}){3}$/;

/** BTN-XXXX-XXXX-XXXX: 60 random bits. */
export function newCode(): string {
  const bytes = new Uint8Array(12);
  globalThis.crypto.getRandomValues(bytes);
  const chars = [...bytes].map((b) => ALPHABET[b & 31]);
  return `BTN-${chars.slice(0, 4).join('')}-${chars.slice(4, 8).join('')}-${chars.slice(8, 12).join('')}`;
}

export function normaliseCode(input: string): string {
  const c = input.trim().toUpperCase().replace(/[^0-9A-Z]/g, '').replace(/^BTN/, '').replace(/[IL]/g, '1').replace(/O/g, '0');
  return c.length === 12 ? `BTN-${c.slice(0, 4)}-${c.slice(4, 8)}-${c.slice(8, 12)}` : input.trim();
}

export interface StoreOptions {
  dir?: string;
  ttlDays?: number;
  maxBytes?: number;
}

export function defaultStoreDir(): string {
  return process.env.BATON_STORE ?? join(homedir(), '.baton', 'store');
}

export class RelayStore {
  dir: string;
  ttlMs: number;
  maxBytes: number;

  constructor(opts: StoreOptions = {}) {
    this.dir = opts.dir ?? defaultStoreDir();
    this.ttlMs = (opts.ttlDays ?? Number(process.env.BATON_TTL_DAYS ?? 7)) * 86400000;
    this.maxBytes = opts.maxBytes ?? Number(process.env.BATON_MAX_BYTES ?? 25 * 1024 * 1024);
    mkdirSync(this.dir, { recursive: true });
  }

  private file(code: string): string {
    if (!CODE_RE.test(code)) throw new Error(`Invalid pickup code: ${code}`);
    return join(this.dir, `${code}.json`);
  }

  private write(r: RelayRecord): RelayRecord {
    const json = JSON.stringify(r);
    if (json.length > this.maxBytes) throw new Error(`Handoff too large (${(json.length / 1048576).toFixed(1)} MB > ${(this.maxBytes / 1048576).toFixed(0)} MB limit)`);
    const f = this.file(r.code);
    writeFileSync(f + '.tmp', json);
    renameSync(f + '.tmp', f);
    return r;
  }

  create(init: { title?: string; from: string; bundle?: BatonBundle; sealed?: SealedPayload }): RelayRecord {
    const now = new Date();
    let code = newCode();
    while (existsSync(join(this.dir, `${code}.json`))) code = newCode();
    return this.write({
      code,
      title: init.title ?? init.bundle?.title ?? 'Untitled handoff',
      createdAt: now.toISOString(),
      updatedAt: now.toISOString(),
      expiresAt: new Date(now.getTime() + this.ttlMs).toISOString(),
      from: [init.from],
      bundle: init.bundle,
      sealed: init.sealed,
      checkpoints: [],
    });
  }

  get(code: string): RelayRecord | undefined {
    const f = this.file(normaliseCode(code));
    if (!existsSync(f)) return undefined;
    const r = JSON.parse(readFileSync(f, 'utf8')) as RelayRecord;
    if (Date.parse(r.expiresAt) < Date.now()) {
      rmSync(f, { force: true });
      return undefined;
    }
    return r;
  }

  addCheckpoint(code: string, c: Omit<Checkpoint, 'seq' | 'at'>): RelayRecord {
    const r = this.get(code);
    if (!r) throw new Error(`No handoff ${code} (expired or never created)`);
    if (r.sealed) throw new Error('This handoff is end-to-end encrypted; checkpoints cannot be added on the server');
    r.checkpoints.push({ ...c, seq: r.checkpoints.length + 1, at: new Date().toISOString() });
    if (c.title) r.title = c.title;
    if (!r.from.includes(c.from)) r.from.push(c.from);
    r.updatedAt = new Date().toISOString();
    return this.write(r);
  }

  list(limit = 20): RelayRecord[] {
    return readdirSync(this.dir)
      .filter((f) => f.endsWith('.json'))
      .map((f) => {
        try {
          return JSON.parse(readFileSync(join(this.dir, f), 'utf8')) as RelayRecord;
        } catch {
          return undefined;
        }
      })
      .filter((r): r is RelayRecord => !!r && Date.parse(r.expiresAt) >= Date.now())
      .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))
      .slice(0, limit);
  }

  purgeExpired(): number {
    let n = 0;
    for (const f of readdirSync(this.dir).filter((x) => x.endsWith('.json'))) {
      try {
        const r = JSON.parse(readFileSync(join(this.dir, f), 'utf8')) as RelayRecord;
        if (Date.parse(r.expiresAt) < Date.now()) {
          rmSync(join(this.dir, f), { force: true });
          n++;
        }
      } catch {
        /* skip */
      }
    }
    return n;
  }
}

// MCP tools that embed Baton inside any AI: the model checkpoints its own work and picks up work from other AIs.
// Used by the remote HTTP relay (ChatGPT / claude.ai connectors) and the local stdio server (Claude Desktop,
// Claude Code, Cursor, Codex, Gemini CLI), so AIs on one machine share ~/.baton/store with no server at all.

import { truncate } from '../core/util.ts';
import type { Tool, ToolContext } from '../mcp/protocol.ts';
import type { Checkpoint } from './checkpoint.ts';
import { renderRecord } from './checkpoint.ts';
import type { RelayStore } from './store.ts';

export const RELAY_INSTRUCTIONS = `Baton moves work between AIs. When the user says "baton", "hand this off", "send this to <another AI>", "save my progress", or before a long task risks losing context, call baton_checkpoint.
Put in EVERYTHING the next AI needs and a share link would lose: the user's prompts verbatim, the FULL contents of files you created or edited (not summaries), outputs of code/tools you ran, decisions with reasons, and next steps.
Give the user the pickup code. To continue work from another AI, call baton_pickup with the code the user gives you, then read the handoff and confirm the latest instruction before acting.`;

const fileSchema = {
  type: 'object',
  properties: {
    path: { type: 'string', description: 'File path as used in the work, e.g. src/app.py or /mnt/data/report.md' },
    content: { type: 'string', description: 'Complete file content, verbatim. Never a summary.' },
    encoding: { type: 'string', enum: ['utf8', 'base64'], description: 'base64 only for binary files' },
  },
  required: ['path', 'content'],
};

export interface RelayToolOptions {
  publicUrl?: string; // e.g. https://relay.example.com, used for viewer links
  allowList?: boolean; // expose baton_list (local stores only)
}

function pickupHint(code: string, opts: RelayToolOptions): string {
  return [
    `Pickup code: ${code}`,
    opts.publicUrl ? `Viewer: ${opts.publicUrl.replace(/\/$/, '')}/h/${code}` : '',
    `To continue in another AI: tell it "baton pickup ${code}" (with the Baton connector enabled), or run \`baton pickup ${code}\` in a terminal.`,
  ]
    .filter(Boolean)
    .join('\n');
}

export function relayTools(store: RelayStore, opts: RelayToolOptions = {}): Tool[] {
  const tools: Tool[] = [
    {
      name: 'baton_checkpoint',
      title: 'Hand off / save progress',
      description:
        'Save the current state of this work to Baton so another AI, teammate or later session can continue it. Creates a new handoff (returns a pickup code) or, with `handoff`, adds a checkpoint to an existing one. Include full file contents, tool/code outputs and verbatim user prompts: this is what share links and exports drop.',
      inputSchema: {
        type: 'object',
        properties: {
          handoff: { type: 'string', description: 'Existing pickup code to add to (omit to create a new handoff)' },
          title: { type: 'string', description: 'Short name for the work' },
          goal: { type: 'string', description: "The user's overall goal" },
          state: { type: 'string', description: 'Where the work stands right now: what is done, what is in progress, what is blocked' },
          decisions: { type: 'array', items: { type: 'string' }, description: 'Decisions made, each with its reason' },
          next_steps: { type: 'array', items: { type: 'string' } },
          open_questions: { type: 'array', items: { type: 'string' } },
          user_prompts: { type: 'array', items: { type: 'string' }, description: "The user's prompts in this conversation, verbatim, oldest first" },
          files: { type: 'array', items: fileSchema, description: 'Every file created or modified, with complete content' },
          tool_outputs: {
            type: 'array',
            items: { type: 'object', properties: { tool: { type: 'string' }, input: { type: 'string' }, output: { type: 'string' } }, required: ['tool', 'output'] },
            description: 'Important outputs of code runs, searches or other tools (the source UI often hides these)',
          },
          notes: { type: 'string' },
        },
        required: ['state'],
      },
      annotations: { readOnlyHint: false, destructiveHint: false, idempotentHint: false, openWorldHint: false },
      run: async (a: Record<string, unknown>, ctx: ToolContext) => {
        const arr = (v: unknown) => (Array.isArray(v) ? (v as unknown[]).map((x) => (typeof x === 'string' ? x : JSON.stringify(x))) : undefined);
        const cp: Omit<Checkpoint, 'seq' | 'at'> = {
          from: ctx.clientName || 'mcp-client',
          title: typeof a.title === 'string' ? a.title : undefined,
          goal: typeof a.goal === 'string' ? a.goal : undefined,
          state: String(a.state ?? ''),
          decisions: arr(a.decisions),
          next_steps: arr(a.next_steps),
          open_questions: arr(a.open_questions),
          user_prompts: arr(a.user_prompts),
          files: Array.isArray(a.files) ? (a.files as Checkpoint['files']) : undefined,
          tool_outputs: Array.isArray(a.tool_outputs) ? (a.tool_outputs as Checkpoint['tool_outputs']) : undefined,
          notes: typeof a.notes === 'string' ? a.notes : undefined,
        };
        if (!cp.state.trim()) throw new Error('`state` is required: describe where the work stands');
        const rec = typeof a.handoff === 'string' && a.handoff ? store.addCheckpoint(a.handoff, cp) : store.addCheckpoint(store.create({ title: cp.title, from: cp.from }).code, cp);
        const { bundle } = renderRecord(rec);
        return [
          `Saved checkpoint ${rec.checkpoints.length} of "${rec.title}".`,
          `Captured: ${bundle.stats.userMessages} prompt(s), ${bundle.stats.artifacts.recovered} file(s), ${bundle.stats.toolResults} tool output(s). Expires ${rec.expiresAt.slice(0, 10)}.`,
          pickupHint(rec.code, opts),
        ].join('\n');
      },
    },
    {
      name: 'baton_pickup',
      title: 'Continue work from another AI',
      description:
        'Load a Baton handoff by its pickup code (BTN-XXXX-XXXX-XXXX) and return its HANDOFF brief: goal, verbatim prompts, state, decisions, next steps, files and what did not transfer. Small text files are included inline; fetch others with baton_get_file.',
      inputSchema: { type: 'object', properties: { code: { type: 'string', description: 'Pickup code, e.g. BTN-7F3K-9QXA-2M4P' } }, required: ['code'] },
      annotations: { readOnlyHint: true, openWorldHint: false },
      run: async (a) => {
        const rec = store.get(String(a.code));
        if (!rec) throw new Error(`No handoff found for ${String(a.code)}. It may have expired; ask the user for the current code.`);
        if (rec.sealed && !rec.bundle) return `Handoff ${rec.code} is end-to-end encrypted. Open it with its full link (including the #key part) in a browser, or run \`baton pickup "<code>#<key>"\`.`;
        const { bundle, files } = renderRecord(rec);
        let budget = 40000;
        const inline: string[] = [];
        for (const art of bundle.artifacts) {
          if (art.content === undefined || art.encoding === 'base64') continue;
          if (art.content.length > budget) break;
          budget -= art.content.length;
          inline.push(`--- files/${art.path} ---\n${art.content}`);
        }
        const rest = bundle.artifacts.filter((x) => x.content !== undefined).length - inline.length;
        return [
          truncate(String(files['HANDOFF.md']), 30000),
          inline.length ? `\n## File contents\n\n${inline.join('\n\n')}` : '',
          rest > 0 ? `\n(${rest} more file(s): call baton_get_file with code ${rec.code} and a path from §6.)` : '',
        ].join('\n');
      },
    },
    {
      name: 'baton_get_file',
      title: 'Get a file from a handoff',
      description: 'Return one file from a Baton handoff (path as listed in its HANDOFF §6, with or without the files/ prefix).',
      inputSchema: { type: 'object', properties: { code: { type: 'string' }, path: { type: 'string' } }, required: ['code', 'path'] },
      annotations: { readOnlyHint: true, openWorldHint: false },
      run: async (a) => {
        const rec = store.get(String(a.code));
        if (!rec) throw new Error(`No handoff found for ${String(a.code)}`);
        const { bundle } = renderRecord(rec);
        const want = String(a.path).replace(/^files\//, '');
        const art = bundle.artifacts.find((x) => x.path === want) ?? bundle.artifacts.find((x) => x.path.endsWith(want));
        if (!art) throw new Error(`No file ${want}. Files: ${bundle.artifacts.map((x) => x.path).join(', ')}`);
        if (art.content === undefined) return `files/${art.path} is ${art.status}: ${art.note ?? 'content not available'}`;
        return art.encoding === 'base64' ? `files/${art.path} is binary (${art.bytes} bytes, ${art.mimeType ?? 'unknown type'}), base64:\n${art.content}` : art.content;
      },
    },
  ];
  if (opts.allowList) {
    tools.push({
      name: 'baton_list',
      title: 'List recent handoffs',
      description: 'List recent handoffs in this Baton store (newest first) with their pickup codes.',
      inputSchema: { type: 'object', properties: { limit: { type: 'integer', minimum: 1, maximum: 100 } } },
      annotations: { readOnlyHint: true, openWorldHint: false },
      run: async (a) => {
        const list = store.list(Number(a.limit ?? 20));
        if (!list.length) return 'No handoffs yet.';
        return list.map((r) => `${r.code}  ${r.updatedAt.slice(0, 16).replace('T', ' ')}  ${r.title}  (from ${r.from.join(', ')}, ${r.checkpoints.length} checkpoint(s)${r.bundle ? ', captured bundle' : ''}${r.sealed ? ', encrypted' : ''})`).join('\n');
      },
    });
  }
  return tools;
}

/** Same tool names, forwarded to a remote relay (BATON_RELAY_URL), so local agents and web AIs share one hub. */
export function remoteRelayTools(url: string, token?: string): Tool[] {
  const call = async (name: string, args: Record<string, unknown>, ctx: ToolContext) => {
    const res = await fetch(url.replace(/\/$/, '') + (url.includes('/mcp') ? '' : '/mcp'), {
      method: 'POST',
      headers: { 'content-type': 'application/json', accept: 'application/json, text/event-stream', ...(token ? { authorization: `Bearer ${token}` } : {}), 'x-baton-client': ctx.clientName },
      body: JSON.stringify({ jsonrpc: '2.0', id: 1, method: 'tools/call', params: { name, arguments: args } }),
    });
    if (!res.ok) throw new Error(`Relay ${url} answered HTTP ${res.status}`);
    const msg = (await res.json()) as { result?: { content?: { text: string }[]; isError?: boolean }; error?: { message: string } };
    if (msg.error) throw new Error(msg.error.message);
    const text = msg.result?.content?.map((c) => c.text).join('\n') ?? '';
    if (msg.result?.isError) throw new Error(text.replace(/^Error: /, ''));
    return text;
  };
  const local = relayTools(new Proxy({} as RelayStore, {}), {});
  return local.map((t) => ({ ...t, run: (args, ctx) => call(t.name, args, ctx) }));
}

// Assemble the on-disk / in-zip layout of a bundle.
//
//   HANDOFF.md      start here (agents and humans)
//   PROMPT.md       one paste-ready block for chat apps
//   TRANSCRIPT.md   full chronological record
//   LOSS_AUDIT.md   what did not transfer, file statuses, integrity
//   index.html      offline viewer
//   bundle.json     canonical machine-readable record (baton.bundle/v1)
//   SKILL.md        makes the folder an Agent Skill ("continue this work")
//   AGENTS.md       pointer for Codex / Cursor / other agents
//   files/…         recovered artifacts
//   replay/…        re-run captured code cells in a sandbox (when available)
//   sinks/…         business-system payloads (optional)

import type { BatonBundle } from '../core/schema.ts';
import type { FileMap } from '../core/zip.ts';
import { renderAgentsMd, renderHandoff, renderPastePrompt, renderSkill } from './handoff.ts';
import { renderHtml } from './html.ts';
import { renderLossAudit, renderTranscript } from './markdown.ts';

export interface RenderOptions {
  skill?: boolean; // default true
  html?: boolean; // default true
  extraFiles?: FileMap; // replay kit, sinks, raw source…
}

export function renderBundleFiles(b: BatonBundle, opts: RenderOptions = {}): FileMap {
  const files: FileMap = {
    'HANDOFF.md': renderHandoff(b),
    'PROMPT.md': renderPastePrompt(b),
    'TRANSCRIPT.md': renderTranscript(b),
    'LOSS_AUDIT.md': renderLossAudit(b),
    'AGENTS.md': renderAgentsMd(b),
    'bundle.json': JSON.stringify(b, null, 2) + '\n',
  };
  if (opts.html !== false) files['index.html'] = renderHtml(b);
  if (opts.skill !== false) files['SKILL.md'] = renderSkill(b);
  for (const a of b.artifacts) if (a.content !== undefined) files[`files/${a.path}`] = a.content;
  Object.assign(files, opts.extraFiles ?? {});
  return files;
}

// HANDOFF.md (agent + human brief), PROMPT.md (one paste-ready block), SKILL.md, AGENTS.md.

import type { BatonBundle } from '../core/schema.ts';
import { slugify, truncate } from '../core/util.ts';
import {
  activityTitles,
  extractOpenThreads,
  fmtBytes,
  fmtDuration,
  fmtTime,
  lastVisibleAssistant,
  reasoningHeadlines,
  sourceLabel,
  splitTurns,
  toolUsage,
  userPrompts,
} from './turns.ts';

function quote(text: string): string {
  return text
    .trim()
    .split('\n')
    .map((l) => `> ${l}`)
    .join('\n');
}

export function renderHandoff(b: BatonBundle): string {
  const prompts = userPrompts(b);
  const first = prompts[0];
  const last = prompts[prompts.length - 1];
  const lastReply = lastVisibleAssistant(b)[0];
  const threads = extractOpenThreads(b);
  const tools = toolUsage(b);
  const s = b.stats;
  const a = s.artifacts;
  const high = b.loss.filter((l) => l.severity === 'high');
  const times = b.events.map((e) => e.time).filter(Boolean) as string[];
  const out: string[] = [];

  out.push('---');
  out.push(`baton: ${b.schema}`);
  out.push(`id: ${b.id}`);
  out.push(`title: ${JSON.stringify(b.title)}`);
  out.push(`source: ${JSON.stringify(sourceLabel(b))}`);
  if (b.source.url) out.push(`source_url: ${b.source.url}`);
  out.push(`root_hash: ${b.integrity.root}`);
  out.push(`generated: ${b.generator.generatedAt}`);
  out.push('---', '');
  out.push(`# Handoff: ${b.title}`, '');
  out.push(`> **If you are an AI agent picking this up:** this folder is an audited transfer of work done in ${b.source.tool}.`);
  out.push('> Read this file first and open `TRANSCRIPT.md` only for the turns you need. `files/` holds the files the source created,');
  out.push('> with the status of each listed in §6. **Do not assume anything in §7 exists.** It was lost in transit and must be rebuilt or re-run.');
  out.push('> Confirm the latest instruction (§3) with the user before large actions.', '');

  out.push('## At a glance', '');
  out.push('| | |', '|---|---|');
  out.push(`| Source | ${sourceLabel(b)}${b.source.url ? ` · <${b.source.url}>` : ''} |`);
  if (times.length) out.push(`| Span | ${fmtTime(times[0])} → ${fmtTime(times[times.length - 1])}${s.durationSeconds ? ` (${fmtDuration(s.durationSeconds)})` : ''} |`);
  out.push(`| Conversation | ${s.userMessages} prompts · ${s.assistantMessages} assistant messages · ${s.reasoningBlocks} reasoning blocks · ${s.toolCalls} tool calls |`);
  out.push(`| Files | ${a.recovered} recovered · ${a.stale} stale · ${a.lost} lost${a.attached ? ` · ${a.attached} attached` : ''} |`);
  out.push(`| Loss | ${high.length ? high.map((l) => `${l.count} ${l.category}`).join(' · ') : 'no high-severity loss'} |`);
  out.push(`| Integrity | \`${b.integrity.root.slice(0, 16)}…\` (run \`baton verify\`) |`, '');

  out.push('## 1. Original goal', '');
  out.push(first ? quote(first.text) : '_No user prompt found._', '');

  out.push('## 2. How the ask evolved (every prompt, verbatim)', '');
  prompts.forEach((p, i) => out.push(`${i + 1}. ${p.time ? `*${fmtTime(p.time)}*: ` : ''}${p.text.trim().replace(/\n+/g, ' ⏎ ')}`));
  out.push('');

  out.push('## 3. Where it left off', '');
  if (last) out.push('**Latest user instruction:**', '', quote(last.text), '');
  if (lastReply) out.push('**Last assistant response (excerpt):**', '', quote(truncate(lastReply.text, 1800)), '');

  out.push('## 4. Open threads and blockers', '');
  out.push('*Heuristically extracted from the final assistant messages. Verify before acting.*', '');
  if (threads.length) for (const t of threads) out.push(`- ${t}`);
  else out.push('- None detected.');
  out.push('');

  out.push('## 5. Reasoning trail (per turn)', '');
  for (const t of splitTurns(b.events)) {
    if (!t.prompt) continue;
    const heads = reasoningHeadlines(t);
    const calls = t.events.filter((e) => e.kind === 'tool_call').length;
    const head = truncate(t.prompt.text.replace(/\s+/g, ' ').trim(), 90);
    out.push(`- **Turn ${t.index}** (“${head}”): ${heads.length ? heads.join(' → ') : 'no reasoning summary'}${calls ? ` · ${calls} tool calls` : ''}`);
  }
  out.push('');

  out.push('## 6. Files', '');
  if (!b.artifacts.length) out.push('_None._');
  else {
    out.push('| Status | Path | Size | Notes |', '|---|---|---|---|');
    const rank = { recovered: 0, attached: 1, stale: 2, lost: 3 } as const;
    for (const f of [...b.artifacts].sort((x, y) => rank[x.status] - rank[y.status] || x.path.localeCompare(y.path))) {
      const link = f.content !== undefined ? `[\`${f.path}\`](files/${encodeURI(f.path)})` : `\`${f.path}\``;
      out.push(`| ${f.status} | ${link} | ${fmtBytes(f.bytes)} | ${(f.note ?? '').replace(/\|/g, '\\|')} |`);
    }
  }
  out.push('');

  out.push('## 7. What the source dropped', '');
  for (const l of b.loss.filter((x) => x.severity !== 'info')) out.push(`- **${l.severity.toUpperCase()} · ${l.category} (${l.count})**: ${l.detail}`);
  if (!b.loss.some((x) => x.severity !== 'info')) out.push('- Nothing significant.');
  out.push('- Full detail: `LOSS_AUDIT.md`.', '');

  if (tools.length) {
    out.push('## 8. Tool activity', '');
    out.push('| Tool | Calls | Inputs available | Outputs available |', '|---|---|---|---|');
    for (const u of tools) out.push(`| \`${u.name}\` | ${u.calls} | ${u.inputsAvailable}/${u.calls} | ${u.outputsAvailable}/${u.outputsTotal} |`);
    const titles = activityTitles(b, 25);
    if (titles.length) out.push('', '**What the tools were used for:** ' + titles.join(' · '));
    out.push('');
  }

  if (b.links.length) {
    out.push('## 9. References seen in the conversation', '');
    for (const u of b.links.slice(0, 40)) out.push(`- <${u}>`);
    if (b.links.length > 40) out.push(`- … ${b.links.length - 40} more in \`bundle.json\``);
    out.push('');
  }

  out.push('## 10. How to continue', '');
  const steps = ['Restate the goal and the latest instruction back to the user in two sentences, and ask whether anything changed.'];
  if (a.recovered + a.stale) steps.push(`Copy \`files/\` into the workspace as the starting tree.${a.stale ? ` Re-check the ${a.stale} stale file(s) against the transcript.` : ''}`);
  if (a.lost) steps.push(`Rebuild the ${a.lost} lost file(s) from their descriptions in \`TRANSCRIPT.md\`. Do not pretend they exist.`);
  if (b.events.some((e) => e.tool?.name === 'container.exec' && e.tool.input)) steps.push('Optionally regenerate derived outputs (PDFs, archives) with `replay/run-in-docker.sh` after reviewing the cells.');
  steps.push('Write `STATE.md` with your understanding (goal, decisions, next steps) so the next handoff starts from it.');
  steps.forEach((st, i) => out.push(`${i + 1}. ${st}`));
  out.push('', '---', `*Generated by Baton ${b.generator.version} · bundle id \`${b.id}\` · \`bundle.json\` is the canonical record.*`);
  return out.join('\n') + '\n';
}

/** A single block a user can paste into any chat UI that cannot read folders. Budgeted to ~12k chars. */
export function renderPastePrompt(b: BatonBundle, budget = 12000): string {
  const prompts = userPrompts(b);
  const lastReply = lastVisibleAssistant(b)[0];
  const threads = extractOpenThreads(b, 6);
  const head: string[] = [];
  head.push(`I'm continuing a piece of work I started in ${b.source.tool}. Below is an exported handoff (made with Baton). Please read it, restate the goal and the current state in a few sentences, list what is missing, and then continue from the latest instruction.`, '');
  head.push(`TITLE: ${b.title}`);
  head.push(`SOURCE: ${sourceLabel(b)}${b.source.url ? ` (${b.source.url})` : ''}`, '');
  head.push('MY PROMPTS SO FAR (verbatim, in order):');
  prompts.forEach((p, i) => head.push(`${i + 1}. ${p.text.trim().replace(/\s+/g, ' ')}`));
  head.push('');
  const files = b.artifacts.map((a) => `- ${a.path} [${a.status}]`).join('\n');
  const loss = b.loss.filter((l) => l.severity !== 'info').map((l) => `- ${l.category} (${l.count}): ${l.detail}`).join('\n');
  const tail: string[] = [];
  if (threads.length) tail.push('OPEN THREADS / BLOCKERS:', ...threads.map((t) => `- ${t}`), '');
  if (files) tail.push('FILES FROM THE PREVIOUS SESSION (status):', files, '');
  if (loss) tail.push('WHAT DID NOT TRANSFER:', loss, '');
  tail.push('Please do not assume lost files exist. Ask me for anything you need.');

  const fixed = head.join('\n').length + tail.join('\n').length + 200;
  const room = Math.max(800, budget - fixed);
  const mid = lastReply ? ['WHERE THE ASSISTANT LEFT OFF (last reply):', truncate(lastReply.text.trim(), room), ''] : [];
  return [...head, ...mid, ...tail].join('\n') + '\n';
}

export function skillName(b: BatonBundle): string {
  return `continue-${slugify(b.title, 50)}`.slice(0, 64).replace(/-+$/, '');
}

export function renderSkill(b: BatonBundle): string {
  const first = userPrompts(b)[0]?.text.replace(/\s+/g, ' ').trim() ?? b.title;
  const desc = truncate(
    `Resume the "${b.title}" work handed off from ${b.source.tool}${b.source.createdAt ? ` (${b.source.createdAt.slice(0, 10)})` : ''}. Original goal: ${first}. Use when the user asks to continue, resume, rebuild, review or extend this work.`,
    1000,
  ).replace(/"/g, "'");
  const last = userPrompts(b).slice(-1)[0];
  return `---
name: ${skillName(b)}
description: "${desc}"
---

# Continue: ${b.title}

This skill folder is a **Baton handoff bundle**: an audited transfer of work done in ${b.source.tool}.
Everything needed to resume is next to this file.

## Steps

1. Read \`HANDOFF.md\` first. It has the goal, every user prompt, where the work stopped, open threads, files and losses.
2. Open \`TRANSCRIPT.md\` only for the turns you need. It is long, and reasoning and tool calls are folded.
3. Treat \`files/\` as the recovered working tree. Only **recovered** files are exact. **stale** files need checking.
   **lost** files do not exist and must be rebuilt (see \`LOSS_AUDIT.md\`).
4. Confirm the latest instruction with the user before large changes${last ? `:\n   > ${truncate(last.text.replace(/\s+/g, ' ').trim(), 300)}` : '.'}
5. When you finish a chunk of work, write \`STATE.md\` (goal, decisions, next steps) next to this file.

## Integrity

\`bundle.json\` is the canonical record. Hash-chain root: \`${b.integrity.root}\`.
If \`baton\` is installed, run \`baton verify .\` to check nothing was altered.
`;
}

export function renderAgentsMd(b: BatonBundle): string {
  return `# AGENTS.md: handoff context

This directory carries work transferred from ${b.source.tool} with Baton (\`${b.schema}\`).

- **Start with \`HANDOFF.md\`.** It has the goal, the verbatim prompts, the current state, open threads and the file status.
- \`TRANSCRIPT.md\` has the full chronological record, and \`bundle.json\` is the canonical machine-readable version.
- \`files/\` is the recovered working tree. Respect the status column (recovered / stale / lost).
- \`LOSS_AUDIT.md\` lists what the source did not include. Never assume a lost file exists.
- Ask the user to confirm the latest instruction before large changes.
`;
}

